  str_story_banner_28 = "Navegador, o Recife tem a habilidade de <color=#FFB400>invocar Runas em locais aleatórios</color>!\nSe não o destruir a tempo, <color=#FFB400>essas Runas vão continuar invocando mais Eclipsitas fortes</color>!",
