  str_story_banner_38 = "Navegador, o inimigo desta vez tem <color=#FFB400>Escudos</color> multicamadas, e cada camada é capaz de <color=#FFB400>resistir uma vez ao dano</color>!",
  str_story_banner_39 = "Esse tipo de Escudo<color=#FFB400>recarrega uma vez a cada duas rodadas</color>, então defina uma estratégia adequada e aproveite a chance crítica para atacar o inimigo!",
  str_story_banner_40 = "Isso é...<color=#FFB400>SAD</color>!\nEle vai <color=#FFB400>atirar chamas periodicamente</color> e <color=#FFB400>causar alto dano</color>! Tome cuidado!",
