  str_story_banner_1001 = "A habil. ativa de Dove permite que ela <color=#FFB400>mude de local</color>. Use-a <color=#FFB400>e vá para outras casas ao alcance da habilidade!</color>",
  str_story_banner_104 = "Hum? É minha vez?",
