  str_story_banner_1003 = "Deixa eu te ajudar. Guie-a para lançar suas habilidades! Lembre Vice de se preparar!",
  str_story_banner_1004 = "Entendido. Só dizer quando devo usar minhas habilidades...",
  str_story_banner_105 = "Essa é a disposição do campo de batalha desta vez? Espera aí. Tive uma ideia!",
  str_story_banner_106 = "O Combo da Srta. Blanc pode atingir todos os monstros na área em forma de diamante, né?\nPodemos contar com ela de novo?",
  str_story_banner_187 = "Vice aprende rápido. Parece que ela prestou atenção às suas instruções anteriores.",
  str_story_banner_107 = "Cuidado. Aqueles novos Eclipsitas que apareceram podem nos atacar a distância.",
