  str_story_banner_111 = "O Combo de Vice pode atacar vários inimigos de longa distância.\n<color=#FFB400>Quanto mais longa a rota de batalha</color>, <color=#FFB400>mais alvos para atacar</color>.",
  str_story_banner_163 = "Tente usar uma rota mais longa para guiá-la no uso de suas habilidades!",
