  str_story_banner_164 = "Vamos entender primeiro os novos elementos e habilidades dos Aurorians através da telepatia.",
  str_story_banner_113 = "Conecte <color=#FFB400>as casas amarelas em uma rota</color>, e Angel, uma Aurorian de <color=#FFB400>Trovão</color>, atacará junto com Vice!",
  str_story_banner_114 = "<color=#FFB400>A casa Verde representa o elemento Floresta</color>, e parece que o Aurorian de Floresta no campo está ansioso para ir.",
  str_story_banner_115 = "Você foi muito bem para a sua primeira batalha. Agora tente sozinho!",
