  str_story_banner_190 = "Quando for formular a rota de batalha, leve em consideração esses tipos de armadilhas.",
  str_story_banner_119 = "Eclipsitas também vêm em formas diferentes. Da próxima vez, não importa o monstro que vier, tenha calma, Navegador.",
  str_story_banner_120 = "<color=#FFB400>É uma Matriz que invoca Eclipsitas constantemente</color>! Eu só as vi em manuais de batalha, mas nunca pensei que acharia uma aqui...",
  str_story_banner_121 = "Ataque a Massa toda vez que puder. E não fique preso pelos Eclipsitas que ela invocar!",
  str_story_banner_191 = "Isso mesmo! Se não puder eliminá-la a tempo, Eclipsitas recém-nascidos vão continuar surgindo!",
  str_story_banner_122 = "O campo de batalha está um pouco mais estreito dessa vez. Cuidado, Navegador!",
