  str_story_banner_138 = "Quanto mais casas azuis ao redor da <color=#FFB400>Vice</color>, mais fortes serão os efeitos das habilidades dela.\nE a <color=#FFB400>Srta. Blanc</color> pode converter as casas ao redor para azuis.",
