  str_story_banner_144 = "Deixa comigo. De certa forma, mostrar o caminho também é minha especialidade!",
  str_story_banner_145 = "Sem pânico. Pense de forma racional antes de tomar uma decisão!",
  str_story_banner_146 = "Está com dificuldade? Lembre-se, a rota de batalha mais longa nem sempre é a escolha certa!",
  str_story_banner_188 = "Você precisa do poder de <color=#FFB400>Zoya</color> para conectar a rota <color=#FFB400>azul</color> e usar sua <color=#FFB400>habilidade de cura</color>!",
  str_story_banner_147 = "É muito importante ter membros com habilidades de cura na batalha!",
  str_story_banner_148 = "<color=#FFB400>Todos os inimigos estão fora do alcance de ataque</color> dessa vez? Precisamos achar um jeito de chegar perto primeiro.",
  str_story_banner_149 = "Alguns Aurorians <color=#FFB400>podem converter diretamente as casas ao redor para um elemento específico</color>, criando uma rota de batalha ideal.",
  str_story_banner_183 = "<color=#FFB400>Srta. Blanc</color> tem essa habilidade, não tem?",
  str_story_banner_150 = "Vamos tentar, e aí você entenderá!",
  str_story_banner_184 = "Desculpe! Não tenho costume de lutar com Celestitas, mas se eu puder ajudar, ótimo!",
  str_story_banner_151 = "Illumina agradece pela sua generosa ajuda, dama de Lumópolis.",
  str_story_banner_185 = "<color=#FFB400>Illumina</color>, <color=#FFB400>Lumópolis</color>...\nDepois de tantos anos, os Aurorians ainda estão mantendo suas casas com afinco.",
  str_story_banner_152 = "<color=#FFB400>Nemesis</color> e Blanc têm habilidades parecidas, mas Nemesis pode <color=#FFB400>causar dano</color> enquanto transforma as casas ao redor em <color=#FFB400>amarelo</color>!",
  str_story_banner_153 = "Usar as habilidades dos Aurorians de converter casas pode gerar uma experiência de batalha mais efetiva!\nLembre-se de aprender e fazer uso dessa estratégia, Navegador!",
  str_story_banner_165 = "Ok. Para priorizar a eficiência, desenhe uma rota que permita que vários Aurorians lutem juntos!",
  str_story_banner_154 = "Aurorians só podem atacar quando viajam por <color=#FFB400>rotas correspondentes aos seus elementos</color>, mas Capitães não têm essa restrição.",
  str_story_banner_250 = "<color=#FFB400>Aurorians de Fogo atacam somente casas Vermelhas</color>, <color=#FFB400>Aurorians de Água atacam casas Azuis</color>, <color=#FFB400>Aurorians de Floresta atacam casas Verdes</color> e <color=#FFB400>Aurorians de Trovão atacam casas Amarelas</color>.",
  str_story_banner_251 = "<color=#FFB400>Escolha as cores correspondentes de forma sensata para os Aurorians atacarem</color>!",
  str_story_banner_155 = "Navegador, bem-vindo ao campo de Desafio. Você só pode usar <color=#FFB400>Dayna</color> para concluir esse desafio.",
  str_story_banner_156 = "Você só tem <color=#FFB400>5 rodadas de batalha</color>. Você não cumprirá o desafio se ficar sem rodadas. Use toda a habilidade de <color=#FFB400>dano de área</color> da Dayna!",
  str_story_banner_157 = "A <color=#FFB400>Habilidade Ativa </color>de Dayna também pode causar dano de área, então use-a ao seu favor!",
  str_story_banner_158 = "Ok, Navegador, cuidado com os Monstros de Bando. Eclipsitas invocados por eles podem causar um forte impacto em você.",
  str_story_banner_159 = "Cuidado, PlayerName! Os Eclipsitas estão um pouco diferentes dessa vez!",
  str_story_banner_160 = "Mexa-se, PlayerName! Este aqui tem um alcance de ataque bem grande!",
  str_story_banner_161 = "Não negligencie os detalhes ao comandar!\nA sobrevivência da sua equipe está em suas mãos.",
  str_story_banner_170 = "Esses Eclipsitas são um pouco anormais! Vamos observá-los de perto primeiro!",
  str_story_banner_171 = "São os batedores do inimigo. Eles querem juntar <color=#FFB400>informação</color> sobre nós num caos!? Temos que recuperar tudo!",
  str_story_banner_172 = "Tente identificar Eclipsitas dessa forma, a <color=#FFB400>informação</color> é com eles!",
  str_story_banner_173 = "Quando recuperar informação suficiente, iremos nos <color=#FFB400>retirar</color> o mais rápido possível.\nA subcidade não vai aguentar muito mais!",
  str_story_banner_174 = "Preste atenção no pequeno Eclipsita voador à distância!\nO manual de batalha os marcou especificamente como \"Perigoso.\"",
  str_story_banner_175 = "Eclipsitas desse tipo se movem muito rápido. Cuidado ao enfrentá-los!",
  str_story_banner_727 = "Oooh! Então esse é um Rastro de Luz.\nAqui é onde nossas batalhas geralmente acontecem!",
  str_story_banner_728 = "Uau! Você realmente faz jus à sua reputação Celestita!\nQue tal me mostrar suas habilidades de comando?",
  str_story_banner_176 = "Está vendo aquela coisa brilhante no campo, jovem? Isso é um <color=#FFB400>cristal de meteorito</color>!",
  str_story_banner_177 = "Ele pode liberar uma energia de Luz condensada<color=#FFB400> para atacar automaticamente o inimigo com mais PV</color>. Você só tem que se aproximar dele! Nem preciso te explicar o resto!",
  str_story_banner_178 = "Ainda há dois Cristais. Vamos ver se podemos eliminar o <color=#FFB400>Eclipsita Grande</color> a distância.\nMexa-se! Mexa-se!",
  str_story_banner_179 = "Droga! É um inimigo de alta ameaça! Navegador, para trás! O-Onde está meu ma-manual?\nDeixe-me achar a descrição...",
  str_story_banner_180 = "É uma <color=#FFB400>avaria de instalação de defesa</color>! As coisas estão ficando mais caóticas agora. Então não perca o foco!",
  str_story_banner_181 = "Talvez vejamos muitas armadilhas complexas como essa no futuro, então vamos tratar essa como um tipo de tutorial!",
  str_story_banner_192 = "PlayerName, você dominou muitas técnicas de combate. Agora eu vou falar sobre uma nova...",
  str_story_banner_193 = "Você sabe que as habilidades dos Aurorians e o tamanho da rota estão relacionados. <color=#FFB400>Se a rota alcançar um certo tamanho</color>, Aurorians podem iniciar a <color=#FFB400>Hora da Aurora</color>.",
  str_story_banner_194 = "Hora da Aurora é um segredo antigo que nem mesmo os próprios Aurorians conhecem bem. Talvez um dia possamos projetar a verdade nesse segredo dos céus.",
  str_story_banner_195 = "Ok, agora vamos criar uma Hora da Aurora!",
  str_story_banner_196 = "Alcance a Hiperconexão para iniciar a Hora da Aurora. Aurorians <color=#FFB400>vão ter outra chance de agir</color>!",
  str_story_banner_197 = "Utilizando-a de maneira sagaz, você colherá os benefícios.",
  str_story_banner_198 = "N-navegador, isso é a Aurora!? É como se o mundo estivesse parado! Agora é a chance perfeita para eliminar os inimigos!",
  str_story_banner_199 = "Esse é um estágio especial. Talvez ele possa melhorar certas técnicas de combate?",
  str_story_banner_201 = "Tudo bem, use o combo de Vice para eliminar os Eclipsitas!",
  str_story_banner_202 = "O terreno Abismal está nos separando do inimigo. Precisamos achar uma medida defensiva.",
  str_story_banner_203 = "O que Vice disse é verdade. Você vê essas casas azuis no campo de batalha? Vamos continuar!",
  str_story_banner_207 = "Corra para a saída!",
  str_story_banner_210 = "Hã, esse Rastro de Luz parece interessante. Talvez seja hora de você controlar a próxima chave para batalhar.",
  str_story_banner_211 = "Está vendo a disposição das <color=#FFB400>casas vermelhas</color>?",
  str_story_banner_212 = "As habilidades dos Aurorians têm relação com o tamanho da rota. Se <color=#FFB400>a rota for conectada para chegar a um certo tamanho</color>, Aurorians vão iniciar a <color=#FFB400>Hora da Aurora</color>.",
  str_story_banner_213 = "A Hora da Aurora é um segredo antigo. Talvez, assim como a Noite Branca,\nseja um mistério que aguarda ser desvendado.",
  str_story_banner_214 = "Ok, agora vamos criar uma Hora da Aurora!",
  str_story_banner_215 = "A situação está ficando difícil. Concentre-se, Celestita.\nVamos ver do que você é capaz!",
  str_story_banner_216 = "Cuidado com essas armas de batalha especiais. Elas <color=#FFB400>atacarão\no primeiro alvo à sua frente em uma linha reta</color>, e isso DÓI!",
  str_story_banner_217 = "Nossos “profissionais” já estão se livrando desses caras, então você só precisa <color=#FFB400>aguentar por mais 7 rodadas</color> para vencer! Você pode checar seu progresso aqui.",
  str_story_banner_218 = "Vamos! Mostre a esses caras que não é fácil nos derrotar!",
  str_story_banner_219 = "Navegador... É urgente. Devemos proteger Eve.",
  str_story_banner_220 = "Eve é vulnerável a ataques inimigos, então precisamos ser mais rápidos do que o inimigo!",
  str_story_banner_221 = "Navegador, contamos com você mais uma vez. Eu acredito em você!",
  str_story_banner_222 = "Navegador, o <color=#FFB400>Coletor</color> está sendo atacado por Eclipsitas!\nNós <color=#FFB400>devemos proteger o dispositivo</color>!",
  str_story_banner_223 = "Agora que os Eclipsitas estão em uma posição vantajosa, temos que eliminar aqueles que escaparam!",
  str_story_banner_224 = "O Coletor também tem alguns recursos que podem nos ajudar a lutar contra esses Eclipsitas. Mas lembre-se de que esses recursos <color=#FFB400>só podem ser usados uma vez por rodada.</color>",
  str_story_banner_225 = "Eclipsitas vão continuar aparecendo, mas devemos aguentar!\nPrecisamos <color=#FFB400>proteger o Coletor</color> da destruição!",
  str_story_banner_226 = "Ativar recursos do Coletor gasta energia. Você notou a <color=#FFB400>Barra de Energia</color>, né?",
  str_story_banner_227 = "O último ataque causou algumas rachaduras no Coletor. Vamos fazer <color=#FFB400>Reparos de Emergência</color>!",
  str_story_banner_228 = "Aaaargh, isso não tem fim! Lembre-se de usar o <color=#FFB400>Escudo de Energia</color> do Coletor quando estiver em apuros! Ele pode aguentar dano <color=#FFB400>3 vezes</color>!",
  str_story_banner_229 = "Esses desgraçados são insanos mesmos, tentando evitar que a gente decole.\nAlém disso, o Rastro de Luz não é o ideal. Temos um problema.",
  str_story_banner_230 = "Ei, ei. Em horas como essa, é melhor usar alguém com habilidade de ataque em grupo, como eu!",
  str_story_banner_704 = "Ela apareceu de novo! A sorrateira Srta. Dayna!?",
  str_story_banner_231 = "Shhh, silêncio. Com o arranjo atual de Lúmina... Isso! Rápido! Coloque-me na posição de <color=#FFB400>Capitão</color>!",
  str_story_banner_232 = "Se machucou? Você devia chamar <color=#FFB400>Zoya</color> para te curar.",
  str_story_banner_233 = "Mas não ignore a excelente rota próxima a ela! <color=#FFB400>Deixe Zoya ficar no topo</color> e nos levar até a rota amarela!",
  str_story_banner_234 = "Agora é minha vez de lidar com esses inimigos espalhados. Navegador, você se lembra como trocar o capitão, né?\nNote que <color=#FFB400>você só pode trocar o capitão 3 vezes por batalha</color>, ok?",
  str_story_banner_235 = "Use os Capitães para mudar o curso da batalha!",
  str_story_banner_236 = "Ugh... Essas pedras irritantes... Insuportável!  Esmague-as!",
  str_story_banner_237 = [[
O brilho desses Eclipsitas...
Acho que temos um problema, PlayerName.]],
  str_story_banner_238 = "\"<color=#FFB400>Resistência a Ataque Físico</color>\" reduz significativamente o <color=#FFB400>dano físico</color>! Parece que só o <color=#FFB400>Combo</color> e a <color=#FFB400>Habilidade Ativa</color> causam dano considerável!",
  str_story_banner_239 = "Esse Eclipsita tem uma forma notável... Se me lembro bem, ele pode lançar um <color=#FFB400>raio poderoso</color>!",
  str_story_banner_240 = "<color=#FFB400>Toque no Eclipsita</color> para ver a localização exata do alvo. Leve-nos para a vitória como sempre!",
  str_story_banner_241 = "Acho que é a primeira vez que encontramos esse tipo de Eclipsita.\nMe dê um segundo para checar seu registro. Esse é problemático...",
  str_story_banner_242 = "Achei! Esse tipo de Eclipsita <color=#FFB400>pode dar bônus para os companheiros ao redor.</color> Devemos eliminá-lo primeiro?",
  str_story_banner_243 = "Tudo que vai, volta? Você se lembra dos Eclipsitas com resistência alta a ataque normal?\nEsse é o oposto. Ele tem <color=#FFB400>Resistência à Habilidade</color>!",
  str_story_banner_244 = "<color=#FFB400>Combos</color> e <color=#FFB400>Habilidades Ativas</color> estão causando <color=#FFB400>bem menos dano</color>! Ou seja, um golpe por vez até cair!",
  str_story_banner_245 = "O quê? Por que esse tipo de Eclipsita está aqui? Para trás, Navegador!",
  str_story_banner_246 = "Esse <color=#FFB400>se autodestruirá</color> quando seu PV cair para um certo valor, causando dano massivo ao redor da área!\nTente usar Ataques a Distância!",
  str_story_banner_247 = "Não é possível... É óbvio que algo ia aparecer...",
  str_story_banner_248 = "\"Esse tipo de Eclipsita foi melhorado com elementos, e só Aurorians com <color=#FFB400>elementos eficazes</color> podem causar dano efetivo a eles.\"",
  str_story_banner_713 = "Esse aqui é ineficaz contra o elemento Água, então deixe comigo.\nSe deixar outros atacarem, vai ficar complicado...",
  str_story_banner_249 = "Graças à sua orientação, percebi que meu poder de combate melhorou bastante nas últimas batalhas!",
  str_story_banner_252 = "Não deixe esses Eclipsitas fugirem! Vamos continuar trabalhando em conjunto!",
  str_story_banner_253 = "Magicianos têm 3 camadas de escudos. Quebrar seus escudos de uma vez é um pouco difícil.",
  str_story_banner_254 = "Sugiro que eu seja o capitão agora!\nAssim, usar <color=#FFB400>Água</color> permite que eu, Vice e Srta. Blanc ataquemos juntos!",
  str_story_banner_255 = "PlayerName, você percebeu? O dano sofrido por esses dois Magicianos é diferente!",
  str_story_banner_256 = "Assim como nós, Eclipsitas têm elementos também.\nAtacar um Eclipsita usando um elemento adequado causa mais dano.",
  str_story_banner_257 = "Água é eficaz contra Fogo, Fogo é eficaz contra Floresta, Floresta contra Trovão e Trovão contra Água!",
  str_story_banner_258 = "PlayerName, guie-nos para derrotar esses Eclipsitas!",
  str_story_banner_259 = "Se você escalar Vice como capitã para a próxima seção de casas amarelas, ela e eu podemos atacar juntos!",
  str_story_banner_301 = "Ah, esses Soldados Lumo me lembram dos velhos tempos!",
  str_story_banner_302 = "<color=#FFB400>Toque</color> para checar suas <color=#FFB400>informações detalhadas</color>!",
  str_story_banner_303 = "Ei! Dê uma olhada nisso! O que são? Lumópolis está usando essas <color=#FFB400>armadilhas</color> obsoletas?",
  str_story_banner_304 = "O cheiro de perigo... Sinto como se eu já tivesse visto a luz amarela desta armadilha em algum lugar.",
  str_story_banner_305 = "Então é a Balista Paralisante! Deixe-me ver... Deve ter um <color=#FFB400>botão gatilho</color> em algum lugar.",
  str_story_banner_306 = "Achei! Hehe, só temos que fazer com cuidado... Espere, parece que tem algo errado com a posição das escórias de Lumópolis... E se...",
  str_story_banner_307 = "Usar esses dispositivos de escória para atingir a si mesmo é divertido! Se tivermos cuidado, e <color=#FFB400>evitarmos ficar na linha de fogo dos dispositivos</color>, está tudo certo!",
  str_story_banner_308 = "Espere! Tem algo estranho com os inimigos na nossa frente! O que Lumópolis está tramando de novo?",
  str_story_banner_309 = "Brock, já ouvi isso antes! Parece que podem gerar fantasmas para <color=#FFB400>evitar ataques</color>!",
  str_story_banner_310 = "Mas os fantasmas <color=#FFB400>não suportam armadilhas paralisantes</color>!\nVamos atingi-los com as armadilhas!",
  str_story_banner_311 = "Mas que droga! Estava bem aqui! Parece que vamos ter mesmo que usar as armadilhas!",
  str_story_banner_312 = "Sim, Brock! É muito chato ter que lidar com esses desgraçados! <color=#FFB400>Use mais dessas armadilhas</color>!",
  str_story_banner_313 = "Podemos deixar a Armadilha de Paralisia atingir esses desgraçados ardilosos, né?\nAcho que consegui!",
  str_story_banner_314 = "Que dispositivo estranho é esse dessa vez!?",
  str_story_banner_315 = "Isso é... Hum, acho que é um tipo de <color=#FFB400>correia de transporte</color>?\nOnde eles acham esses aparelhos esquisitos?",
  str_story_banner_316 = "Cuidado! Essa coisa se mexe, então não seja lançado para os inimigos!",
  str_story_banner_317 = "Hã? Esse Eclipsita... é meio fofinho?",
  str_story_banner_318 = "Não, não, não se engane com sua aparência!\nSe é um Eclipsita, é nosso inimigo!",
  str_story_banner_712 = "... Vice tem razão. Eclipsitas desse tipo podem <color=#FFB400>curar seus companheiros</color>, então é melhor lidar com eles primeiro.",
  str_story_banner_319 = [[
Esse monstro grande parece perigoso...
PlayerName, cuidado!]],
  str_story_banner_320 = "O que é esse Eclipsita fofo?\nAcho que ele não estava no Manual de Batalha...",
  str_story_banner_321 = "Tentando me enganar com sua aparência de novo? Navegador, afaste-se por hora!\nDeixe a luta com a gente!",
  str_story_banner_322 = "PlayerName, você vê o <color=#FFB400>Redemoinho</color> no chão?",
  str_story_banner_323 = "Parece que...<color=#FFB400>podemos viajar rápido para lá e para cá entre dois Redemoinhos</color>! Sensacional!",
  str_story_banner_324 = "É uma nova forma de Eclipsita de novo? Estou chegando ao fim do manual de batalha.",
  str_story_banner_325 = "PlayerName, pise nessas <color=#FFB400>casas de runa</color>, ou elas <color=#FFB400>invocarão outros Eclipsitas!</color>",
  str_story_banner_326 = "É um <color=#FFB400>Siforbe!</color>!\nEsses monstros <color=#FFB400>podem absorver casas nos arredores do mesmo elemento para aumentar seu dano</color>!",
  str_story_banner_327 = "Essa é a <color=#FFB400>Arena Sombria</color> de Umbraton! Só precisamos derrotar esses monstros que cospem Ouro! Simples assim!",
  str_story_banner_328 = "Mas por que os PVs desses Eclipsitas são tão estranhos?\nTem algo errado...",
  str_story_banner_329 = "É isso. Toda vez que o PV de <color=#FFB400>Goldor Sombrio</color> ficar abaixo de um certo valor, vai iniciar a <color=#FFB400>Imunidade ao Dano</color> nessa rodada. Que persistente...",
  str_story_banner_330 = "Goldors Sombrios também podem fazer ataques de <color=#FFB400>longo alcance</color>. Escolha uma boa estratégia e acabe com o inimigo encrenqueiro!",
  str_story_banner_331 = "Isso! Ativamos a <color=#FFB400>Rodada Bônus</color>! Que sorte a nossa! Navegador, venha logo!",
  str_story_banner_332 = "<color=#FFB400>Existe um limite de tempo para a Rodada Bônus</color>, então precisamos matar esses Eclipsitas o mais rápido possível! Faça bom uso das Habilidades Ativas dos Aurorians!",
  str_story_banner_333 = "Você percebeu os <color=#FFB400>sinais</color> no campo? Eles podem <color=#FFB400>disponibilizar um escudo redutor de dano</color> para Eclipsitas.\nPlaneje com base nisso!",
  str_story_banner_334 = "Na batalha Neve Esquecida, todo estágio tem características próprias, então lembre-se de checar isso!",
  str_story_banner_335 = "Com tantos Eclipsitas sendo atraídos, devíamos ter desmontado a Colossus antes de confiscá-la... Ei!",
  str_story_banner_336 = "Há muitas <color=#FFB400>pedras</color> aqui que podem dificultar a movimentação. Meu Combo pode removê-las.",
  str_story_banner_729 = "Você é quem manda, PlayerName!",
  str_story_banner_337 = "Uau! Às vezes aparecem uns itens misturados com essas pedras. Vamos ver!",
  str_story_banner_338 = "Bem, isso é bem chato. Sem falar que há muitos Eclipsitas por perto. Vamos fazer bom uso desses itens!",
  str_story_banner_339 = "Esse lugar parece o um resto de um <color=#FFB400>depósito antigo</color>. Talvez você consiga muitos Fragmentos de Texto aqui!",
  str_story_banner_340 = "Está vendo a <color=#FFB400>armadilha</color> no chão? Se passarmos por três casas de armadilha, deve abrir!",
  str_story_banner_341 = "Vamos começar!",
  str_story_banner_342 = "Acho que estamos no território dos <color=#FFB400>ladrões de túmulo</color>. Eles têm muitos itens!",
  str_story_banner_343 = "Se <color=#FFB400>não os capturarmos e derrotá-los</color>, eles vão <color=#FFB400>fugir</color>!",
  str_story_banner_344 = "Vamos pegar o espólio que deveria ser nosso!",
  str_story_banner_345 = "Ei, ei. Esse não é <color=#FFB400>Tanchi</color>, o Cavaleiro Novato?\nParece que ele ativou a armadilha e agora está preso nela.",
  str_story_banner_346 = "Droga! Eclipsitas estão se juntando. Não podemos hesitar! <color=#FFB400>Vamos proteger esse Cavaleiro Novato</color>!",
  str_story_banner_347 = "Cuidado! Essa armadilha é muito perigosa.",
  str_story_banner_348 = "Esse tipo de armadilha é ativado quando se pisa nela. Use-a com cuidado.",
  str_story_banner_501 = "Navegador, chegou a hora de te passar informação mais completas.",
  str_story_banner_502 = "Além do recrutamento, há outros sistemas na Colossus que precisam de conserto.\nFique à vontade para explorá-los nas suas futuras aventuras!",
  str_story_banner_503 = "<color=#FFB400>Eclipsitas Grandes</color> apareceram!\nMas isso significa que temos <color=#FFB400>mais ângulos de ataque também</color>!",
  str_story_banner_166 = "Essa batalha foi ótima! Decidi que vou te chamar de Navegador!\nA partir de agora, você será nosso líder!",
  str_story_banner_702 = "Não transfira a responsabilidade de Capitão para outra pessoa assim.",
  str_story_banner_504 = "Por que você não lança o resto dos seus membros na batalha?\nVamos formar um esquadrão Celetista-Aurorian poderoso!",
  str_story_banner_505 = "Agora os novos membros estão prontos!",
  str_story_banner_506 = "Navegador, as missões atribuídas pelo sistema estão prontas e precisam da sua avaliação!",
  str_story_banner_507 = "O que é essa coisa piscando? Algum tipo de notificação do sistema da Colossus? Vamos tocar para ver?",
  str_story_banner_508 = "Isso é um tipo de <color=#FFB400>Recomp. da Missão</color>, é?\nQuer dizer que toda vez que um concluirmos um estágio, vamos ganhar um benefício assim?",
  str_story_banner_509 = "Quando você não souber como continuar a aventura, pode ir para a última orientação via tela de Missão!",
  str_story_banner_510 = "É isso aí! Sempre que possível, <color=#FFB400>suba o nível dos seus Aurorians</color> para deixá-los em ótima condição!",
  str_story_banner_511 = "Você é bem informado! Esse é um bom momento pra atacar! Siga-me!",
  str_story_banner_512 = "Com essas missões você se desenvolverá mais rápido! Só precisa se familiarizar com o mundo rapidamente! Primeiro, vamos ver o que está disponível!",
  str_story_banner_513 = "Quem é você? Como posso ajudar?",
  str_story_banner_514 = "Cof, parece que um companheiro em potencial quer participar.",
  str_story_banner_515 = "A força da Dayna é de alto nível. E ela venceu vários torneios secretos em Umbraton,\nmas ela também é bem ardilosa.",
  str_story_banner_516 = "Tudo bem, tudo bem. Vamos continuar com nossa aventura!",
  str_story_banner_517 = "É hora de usar Lumâmbar para <color=#FFB400>recrutar Aurorians</color>, Navegador!",
  str_story_banner_518 = "Como Vice disse, use <color=#FFB400>Lumâmbar</color> para lançar um sinalizador, e quem sabe algum Aurorian responda.",
  str_story_banner_182 = "Mas eu não posso prever onde a luz do destino vai levar sua voz,\ne quem a responderá...",
  str_story_banner_519 = "Alguns Aurorians responderam! Vamos ficar prontos para colaborar com eles.",
  str_story_banner_532 = "É hora de melhorar o poder de combate de todos!\nDove, traga seus materiais de melhoria.",
  str_story_banner_703 = "Você quer requisitar minha propriedade de novo!?",
  str_story_banner_520 = "Viu? Tem recompensas que você pode retirar de novo! Lembre-se de ficar de olho nessas regalias.",
  str_story_banner_521 = "Você pode recrutar 10 Aurorians com esse presente valioso!\nNossa equipe está crescendo!",
  str_story_banner_522 = "PlayerName, acabamos de receber notícias do Norte.\nParece que algumas Experiências novas apareceram!",
  str_story_banner_523 = "Parece que tem muitos tipos de Experiências que podem fornecer recursos para Aurorians evoluírem.\nDê uma olhada quanto tiver tempo.",
  str_story_banner_524 = "Ah, e um novo cronograma foi ativado. Seria melhor você confirmá-lo o mais rápido possível.\nLeve a Vice para dar uma olhada, PlayerName.",
  str_story_banner_260 = "Essas missões <color=#FFB400>atualizam todo dia</color>! Talvez elas nos ajudem a armazenar alguns recursos necessários!",
  str_story_banner_525 = "Ganhe recompensas incríveis como Lumâmbars ao acumular Pontos de Atividade.",
  str_story_banner_705 = "Elas podem ser usadas para cobrir os gastos diários para a Colossus no futuro. Também precisamos aprender como operar a Colossus daqui pra frente.",
  str_story_banner_706 = "Parece que ela já se promoveu para ser sua segunda-comandante.",
  str_story_banner_526 = "Navegador, cuidado à frente!",
  str_story_banner_527 = "A estrada se divide aqui. Uma leva você adiante na sua aventura e a outra parece que <color=#FFB400>se expande em outro estágio</color>.\nSe tiver interesse, dê uma olhada!",
  str_story_banner_528 = "Você pode encontrar algumas batalhas especiais nessas rotas paralelas. Dê uma olhada quando tiver tempo!",
  str_story_banner_529 = "Espere. Tocar no Guia de Missão pode te levar direto para o seu destino,\nmas achei outro lugar que pode nos levar lá! Siga-me!",
  str_story_banner_530 = "Na tela início, toque em <color=#FFB400>Missões</color> para ir direto para seu destino de aventura!\nVocê não sabia disso, né? Eu acabei de descobrir!",
  str_story_banner_531 = "Que criança teimosa.",
  str_story_banner_533 = "Uma <color=#FFB400>Ascensão Aurorian</color> não só melhora as habilidades do Aurorian, mas também aumenta o <color=#FFB400>Nível Max.</color> do Aurorian, que é uma forma muito importante de desenvolvimento.",
  str_story_banner_534 = "Você pode ascender um Aurorian após coletar todos os materiais exigidos para a <color=#FFB400>Ascensão do Aurorian</color> e melhorá-lo até o nível máximo atual.",
  str_story_banner_535 = "Navegador, você acabou de coletar um material valioso: uma <color=#FFB400>Pedra-Coração</color>!\nAgora podemos fazer um <color=#FFB400>Avanço de Aurorian</color>! Siga-me!",
  str_story_banner_536 = "Realizar um Avanço de Aurorian <color=#FFB400>aumentará os atributos do Aurorian</color> e melhorará suas <color=#FFB400>habilidades</color>!\nExperimente!",
  str_story_banner_537 = "Toda a Colossus está iluminada! Isso significa que podemos fazer reparos simples de sistema?",
  str_story_banner_707 = "De qualquer forma, vamos checar rapidamente a Colossus! Como um santuário, a condição de Soroz também é importante!",
  str_story_banner_708 = "Muitas áreas fechadas podem ser desbloqueadas agora.\nPodemos enfim fazer bom uso daqueles espaços inativos por 17 anos!",
  str_story_banner_538 = "Eu quase me esqueci. Vamos pegar a recém-recrutada <color=#FFB400>Srta. Blanc</color> para se juntar à equipe!",
  str_story_banner_539 = "Todos estão prontos! Vamos continuar a aventura!",
  str_story_banner_540 = "A entrada para o Território Secreto está desbloqueada. Vamos explorar os arredores um pouco.",
  str_story_banner_541 = "A entrada do Território Secreto não abre por muito tempo, então explore o máximo que quiser enquanto estiver aberta!",
  str_story_banner_542 = "No Território Secreto, nós consumimos MS em vez de Prisma. Esse é um recurso incrível produzido pela Colossus!",
  str_story_banner_543 = "Cada rodada da batalha do Território Secreto custa 1 MS. Não podemos mais continuar após usarmos todo o MS!",
  str_story_banner_544 = "Há muitas rotas para escolher quando batalhar no Território Secreto. Mas todas elas levam ao mesmo destino. Então cuidado ao escolher as rotas porque elaes produzem diferentes efeitos de batalha.",
  str_story_banner_545 = "O desafio... para ganhar dinheiro, é necessário para... consertar e proteger a Colossus, bem como o custo da nossa comida... despesas...",
  str_story_banner_546 = "Não deixe Vice se animar demais quando ela ouvir falar de dinheiro! Descanse e fique bem!\nEla tem trabalhado bastante!",
  str_story_banner_547 = "Parece que há uma variedade de <color=#FFB400>dificuldades</color> para escolher. Escolha uma que consiga realizar.",
  str_story_banner_548 = "A Afinidade entre você e os Aurorians pode influenciá-los um pouco, então cuide mais deles.",
  str_story_banner_549 = "Você tem algum Aurorian em mente? Por exemplo, talvez <color=#FFB400>Vice</color>, que acabou de se machucar sozinha para proteger você? Por que não a motiva?",
  str_story_banner_550 = "Que tal escolher um <color=#FFB400>presente</color> para a Vice? Talvez ela fique feliz dessa forma.",
  str_story_banner_551 = "<color=#FFB400>Dar Presentes</color> pode melhorar sua <color=#FFB400>Afinidade</color> com Aurorians, desbloquear mais <color=#FFB400>Arquivos</color> e até melhorar alguns dos seus <color=#FFB400>atributos</color>.",
  str_story_banner_552 = "Escolha um presente aqui e em seguida toque em Dar Presentes abaixo!",
  str_story_banner_553 = "Estou tão feliz que Charon está são e salvo... Quem diria que aquele cara teria esse tipo de “surpresa” escondida?",
  str_story_banner_554 = "PlayerName, <color=#FFB400>Contos de aventura</color> foi desbloqueado! Você gostaria de ver como são as aventuras não principais da história?",
  str_story_banner_556 = "Se estiver cansado de aventuras, por que não relaxa e faz esses capítulos extras?",
  str_story_banner_557 = "PlayerName, você ainda se lembra das <color=#FFB400>Missões Expansoras</color>? Parece que concluímos muitas. Dê uma olhada!",
  str_story_banner_558 = "Nada mal, hein? Vamos retirar as recompensas!",
  str_story_banner_559 = "Dayna tem mesmo um olhar penetrante... Vamos concluir essas missões rápido e\nrecrutá-la para nossa equipe!",
  str_story_banner_560 = "Eu acabei de pegar isso de um Eclipsita. É pesado e parece algo importante. Talvez possa ser útil?",
  str_story_banner_561 = "Esse é o <color=#FFB400>Plugin Central</color>! É um componente importante na restauração da Colossus e na melhoria da Ponte!",
  str_story_banner_562 = "Anda, vamos ver se essa coisa ainda funciona. Siga-me!",
  str_story_banner_563 = "Use o <color=#FFB400>Plugin Central</color> para melhorar sua Ponte. Você sabe como fazer isso?",
  str_story_banner_564 = "Não temos materiais suficientes para melhorar agora! Temos que ir à <color=#FFB400>Incursão para Recursos Colossus</color> para mais!",
  str_story_banner_565 = "PlayerName. Um dos módulos entre meus dados antigos não utilizados foi ativado. É uma coordenada!",
  str_story_banner_567 = "Aqui está...",
  str_story_banner_568 = "Esse lugar parece sinistro. Talvez nenhum Aurorian tenha explorado esse local antes.",
  str_story_banner_569 = "Não sei o que essas coordenadas significam, mas parece que elas estão mexendo com minha memória.\nVocê gostaria de dar uma olhada?",
  str_story_banner_570 = "O nível Lúmina nessa área é bem fraco. É como estar do outro lado do continente governado por Eclipsitas.",
  str_story_banner_571 = "Entrar sem proteção seria suicídio. Deixe-me ver se tem algum item que possamos utilizar na Colossus.",
  str_story_banner_573 = "Por essa não esperava. Ainda tenho essas coisas?\nEsse mini <color=#FFB400>Sol Artificial</color> pode evitar que sejamos corrompidos pela escuridão desse Território Secreto!",
  str_story_banner_574 = "É claro, a Lúmina que ele fornece não é ilimitada.\nPelo <color=#FFB400>\"MS”</color> dá para ver o quanto de energia sobrou.",
  str_story_banner_575 = "Conforme explora, o <color=#FFB400>MS</color> diminuirá gradualmente. Quando chegar a <color=#FFB400>0</color>, você deve escapar. Aja de acordo com sua capacidade!",
  str_story_banner_576 = "Tem um lugar especial na Colossus para recarga. E se quiser conquistar o Território Secreto, você precisará desbloquear aquele cômodo.",
  str_story_banner_577 = "O que você está resmungando? O nome é PlayerName, certo?",
  str_story_banner_578 = "Se você está pensando sobre o Território Secreto, peço que aja com cautela.\nAs recompensas são ótimas, mas já tem bastante exploradores enterrados lá.",
  str_story_banner_722 = "Temos mais uma coisa importante para fazer. Saia quando tiver visto o bastante. Vou te esperar do lado de fora.",
  str_story_banner_579 = "PlayerName, recebemos uma nova mensagem! Dê uma olhada na <color=#FFB400>Caixa</color>!",
  str_story_banner_580 = "PlayerName, uma nova história foi desbloqueada em <color=#FFB400>Capítulos Extras</color>.\nQuer ver?",
  str_story_banner_581 = "<color=#FFB400>Abaixe a alavanca</color> e conclua o recrutamento de Aurorians!",
  str_story_banner_582 = "PlayerName!\nPodemos usar o <color=#FFB400>transportadoras</color> nós pegamos do Colosso aqui!\nEles reduzirão a quantidade de Prisma necessária para concluir os estágios e conceder recursos imediatamente!",
  str_story_banner_583 = "Transportes são muito valiosos, então reflita com cuidado quando vai usá-los!",
  str_story_banner_584 = "Há também um <color=#FFB400>limite de armazenamento</color> para Transportes, melhor usar só quando necessário!",
  str_story_banner_585 = "A exploração começou!\nLembre-se de ver o perfil do monstro antes de lutar no Território Secreto!",
  str_story_banner_586 = "Essa sala é diferente, PlayerName!\nA presença do inimigo parece ser muito predominante.",
  str_story_banner_587 = "Como era de esperar, é um <color=#FFB400>Estágio Elite</color>! Cada Estágio Elite tem atributos únicos de estágio, então cuidado ao lidar com eles!",
  str_story_banner_588 = "Finalmente, chegamos ao <color=#FFB400>salão</color>. Podemos <color=#FFB400>recuperar MS.</color> aqui e descansar! Você deve estar com fome.",
  str_story_banner_715 = "*Tire a bolsa com a travessa de órgão de verme de areia grelhado no carvão*",
  str_story_banner_589 = "A pressão aqui é ainda mais pesada do que nos Estágios Elite. Não preciso falar mais nada, certo?\nAbaixo de nós está o grande clímax.",
  str_story_banner_590 = "Essas são todas as <color=#FFB400>relíquias</color> que coletamos!\nCada relíquia tem uma característica diferente, apesar de só funcionarem no Território Secreto!",
  str_story_banner_716 = "Seria bom se pudéssemos removê-las. Talvez elas possam cobrir parte do gasto de operação e manutenção da Colossus. Dove também está querendo um aumento.",
  str_story_banner_591 = "Ufa... finalmente acabou.",
  str_story_banner_592 = "Mas o que Mendelson disse sobre Schummer e aqueles três componentes...\nOnde vamos encontrá-los?",
  str_story_banner_593 = "Uma nova fonte de sinal surgiu. Quer investigar a fonte?\nParece que é um novo desafio.",
  str_story_banner_594 = "É um campo de teste chamado a '<color=#FFB400>Torre</color>'!",
  str_story_banner_595 = "Melhorar sua força um pouco antes de embarcar na próxima aventura é sempre uma opção!\nVamos descobrir mais sobre isso primeiro, ok?",
  str_story_banner_596 = "Torre... Uma ruína antiga misteriosa. Já que está aqui, tem interesse em tentar?",
  str_story_banner_597 = "É claro! PlayerName, muitos já desafiaram a Torre, mas eu nunca tive chance de acessá-la. Vamos tentar dessa vez!",
  str_story_banner_598 = "Tudo bem, me siga então.",
  str_story_banner_599 = "A Torre é o local onde os <color=#FFB400>quatro elementos</color> se unem. Assim, há quatro deles com um limite de desafio para cada um. Vamos para a <color=#FFB400>Torre Congelada</color> dar uma olhada.",
  str_story_banner_600 = "PlayerName, você precisa começar do <color=#FFB400>primeiro nível</color> e guiar os Aurorians para cima. <color=#FFB400>Só Aurorians do mesmo elemento são permitidos</color> em cada torre!",
  str_story_banner_601 = "Aguardo ansiosamente pelo seu desempenho. Boa sorte! Vou esperar vocês do lado de fora.",
  str_story_banner_602 = "Entendo. É um desafio chamado <color=#FFB400>Noite Branca, Área Sombria</color>, que oferece bastante <color=#FFB400>dinheiro</color> para derrotar inimigos.",
  str_story_banner_603 = "Essas missões podem oferecer ganhos extras. Então não deixe de dar uma passadinha e concluí-las quando tiver tempo. Hum, o que é essa <color=#FFB400>Noite Branca, Área Sombria</color>?",
  str_story_banner_604 = "PlayerName, você notou que no Território Secreto o PV de cada Aurorian é <color=#FFB400>individual</color>?",
  str_story_banner_605 = "Nossos membros da equipe perceberam quão perigosas as coisas estão ficando.\nTalvez estejamos dependendo muito do Capitão?",
  str_story_banner_606 = "Acompanhe as mudanças no campo de batalha no Território Secreto! Afinal, é a primeira vez de todos aqui.",
  str_story_banner_607 = "Dê a ordem! Confiamos totalmente em você, PlayerName!",
  str_story_banner_608 = "PlayerName, esses Aurorians encontraram algumas <color=#FFB400>coisinhas</color>...\nVocê pode ter interesse nelas, então venha conferir.",
  str_story_banner_609 = "Esse é um <color=#FFB400>sistema terminal</color> que permite aos usuários se comunicarem entre si remotamente. Eu já dei todo o acesso necessário a vocês.",
  str_story_banner_610 = "Comparado a um velho como eu, você deve ser capaz de entender facilmente.",
  str_story_banner_611 = "Parece que é melhor discutir algumas coisas cara a cara.",
  str_story_banner_650 = "Acabamos de receber um novo item. Que marcas fascinantes!",
  str_story_banner_651 = "A análise mostra que é um <color=#FFB400>Cubo do Território Secreto,</color> que mostra a localização de Territórios Secretos!",
  str_story_banner_652 = "Digite o padrão de superfície no banco de dados do Colossus, talvez isso desbloqueie o Exploration Office! Me siga!",
  str_story_banner_653 = "Eu inseri o mapa no banco de dados e analisei todas as informações necessárias para construir o Escritório de Exploração.",
  str_story_banner_654 = "Agora, vamos começar a construir o <color=#FFB400>Escritório de Exploração</color>!",
  str_story_banner_1201 = "O que é isso? Parece tão estranho... Será que é um tipo de armadilha?",
  str_story_banner_1202 = "Acho que vai explodir se isso atingir alguém!\nSerá que tem um jeito especial de resolver isso?",
  str_story_banner_1203 = "De alguma forma é... inesperadamente interessante.\nEm comparação com a lâmina, esse estilo é divertido também.",
  str_story_banner_714 = "Mas não devemos baixar a guarda! Se eu posso usar esse método, o inimigo também pode!",
  str_story_banner_1204 = "PlayerName, lembre-se de <color=#FFB400>subir o nível</color> dos Aurorians. Assim, poderá vencer a batalha com facilidade!",
  str_story_banner_1205 = "Dessa vez, vamos subir o nível da <color=#FFB400>Srta. Blanc</color>!",
  str_story_banner_1206 = "Você ainda se lembra de como fazer isso? Experimente!",
  str_story_banner_1207 = "Podemos <color=#FFB400>chutar</color> Bombas Hidráulicas?\nQuer dizer que podemos jogar Eclipsitas nas Bombas Hidráulicas? Vamos tentar!",
  str_story_banner_1208 = "É raro encontrar essas espécies estranhas de Eclipsitas.",
  str_story_banner_1209 = "Cuidado! Esses Eclipsitas têm uma <color=#FFB400>habilidade de empurrar</color> extraordinária! É bom anotar isso.",
  str_story_banner_2001 = "É a primeira vez que vê o interior da Colossus, né? Parece bem bagunçado agora porque a parte mais importante, o <color=#FFB400>Plugin Central</color>, sumiu.",
  str_story_banner_2002 = "Se possível, fique atento a um <color=#FFB400>Plugin Central</color> durante suas aventuras, porque isso pode ajudar a recuperar meu poder e permitir que eu use mais recursos.",
  str_story_banner_2003 = "Ok, vamos descobrir o que você pode fazer na Colossus. Os recursos da Colossus são alimentados por Lúmina, então vamos nos familiarizar com isso.",
  str_story_banner_2004 = "Vamos desbloquear a <color=#FFB400>Rede Lúmina</color> primeiro.",
  str_story_banner_709 = "Além disso, precisamos de <color=#FFB400>Vaga-lumes</color> para desbloquear e melhorar os cômodos. Esses carinhas trabalhadores estão com a gente há 17 anos.",
  str_story_banner_2005 = "Está desbloqueado! Excelente! Agora posso oferecer abrigo e proteger a todos.",
  str_story_banner_2006 = "Agora, dê uma olhada na <color=#FFB400>Rede Lúmina</color>.",
  str_story_banner_2007 = "Essa é a <color=#FFB400>Rede Lúmina</color>. Você pode construir <color=#FFB400>4</color> delas, mas tem que desbloqueá-las uma por uma.",
  str_story_banner_2008 = "Uma Sala Lúmina não só <color=#FFB400>fornece Lúmina</color>, mas <color=#FFB400>aumenta a recuperação de Vaga-lumes</color> também. Veja, os Vaga-lumes já estão vindo.",
  str_story_banner_2009 = "Ok, vamos olhar outras informações sobre a Rede Lúmina.",
  str_story_banner_2010 = "<color=#FFB400>Aurorians podem ser atribuídos</color> para trabalhar nos cômodos da Colossus para melhorar os efeitos dos seus recursos.\nExperimente!",
  str_story_banner_2011 = "Cada Aurorian tem sua especialidade. Devemos escolher um Aurorian que consiga trabalhar na Sala Lúmina.",
  str_story_banner_2012 = "Muito bem, vamos para o <color=#FFB400>Pilar Prisma</color> agora. É uma área muito importante!",
  str_story_banner_2013 = "Boas-vindas à <color=#FFB400>Ponte</color>! Essa é a área mais importante da Colossus, então deixe-me contar o que já aprendi sobre a Colossus quando eu estava em Illumina!",
  str_story_banner_2014 = "A Ponte pode aumentar o <color=#FFB400>Ânimo</color> máx. na Colossus! Veja o detalhe aqui!",
  str_story_banner_2015 = "Hum... Vejamos... Onde encontrar detalhes sobre a Ponte...",
  str_story_banner_2016 = "Ah, aqui está! Se você tiver coletado um Plugin Central, pode usá-lo para melhorar a Ponte daqui!",
  str_story_banner_2017 = "PlayerName, ainda não há Aurorians atribuídos na Ponte! Você esqueceu como fazer?",
  str_story_banner_710 = "Eu sou uma boa opção! Já operei as plataformas de controle antes e aprendi como operar os sistemas de Soroz! Por favor, me deixe ficar na ponte!",
  str_story_banner_711 = "Essa aprende rápido...\nVice parece a melhor pessoa para esse trabalho no momento.",
  str_story_banner_2018 = "A propósito, eu tirei uns dias para avaliar os recursos restantes, e parece que não temos o suficiente.",
  str_story_banner_2019 = "Talvez seja melhor explorar o interior da Colossus. Talvez algum lugar que possa gerar recursos esteja online!",
  str_story_banner_2021 = "Parece que é um convite para trabalhar junto com outros poderes de Aurorian? Não sei muito sobre isso, mas esses caras são bons em coletar todo tipo de material estranho.",
  str_story_banner_2022 = "Esta é a <color=#FFB400>Câmara Estelar</color>, uma instalação muito importante!",
  str_story_banner_2023 = "A Câmara Estelar geralmente produz <color=#FFB400>Pedras-Coração</color> valiosas, mas às vezes <color=#FFB400>Joias Estelares</color> e <color=#FFB400>Joias Estelares SS</color> podem aparecer também. Planeje isso quando tiver tempo!",
  str_story_banner_2024 = "É mais rápido coletar pedra-coração à medida que o nível da Câmara Estelar aumenta.\nAtribuir o Aurorian certo também melhora a taxa de coleta! Experimente!",
  str_story_banner_2025 = "Você se lembra do <color=#FFB400>Prisma</color> que usamos na batalha anterior? Ele é essencial pra ajudar o Navegador a recarregar a energia usada em habilidades psíquicas.",
  str_story_banner_2026 = "O Pilar Prisma é uma instalação muito preciosa que pode converter Lúmina em <color=#FFB400>Prismas</color>.",
  str_story_banner_2027 = "Você pode ver dados sobre o Pilar Prisma na barra rápida de informação no canto inferior esquerdo.",
  str_story_banner_2028 = "Veja mais detalhes aqui.",
  str_story_banner_2029 = "Essa é a <color=#FFB400>Estação de Recursos</color>! Me lembro de todas as coisas importantes sobre ela!\nDeixe-me apresentá-la! Cof!",
  str_story_banner_2030 = "A Estação de Recursos pode fabricar <color=#FFB400>Transportes</color>. Você pegou alguns, né?",
  str_story_banner_731 = "Estes são Fireflies especiais que lutam em seu nome. <color=#FFB400>Eles reduzirão a quantidade de Prisma necessária para concluir os estágios e conceder recursos imediatamente</color>!",
  str_story_banner_2031 = "Vamos ver como você pode checar os dados da Estação de Recursos.",
  str_story_banner_2032 = "A iniciação de várias Incursões para Recursos depende do nível da Estação de Recursos.\nVocê pode atribuir Aurorians aqui também, não se esqueça!",
  str_story_banner_2033 = "Muito bem, vamos ver como usar Transportes!",
  str_story_banner_2034 = "PlayerName, lembra do que falamos antes sobre explorar o Território Secreto? Parece que o cômodo onde você está agora pode ser usado para transformar \"<color=#FFB400>Sóis Artificiais</color>\"!",
  str_story_banner_2035 = "Vice parece me conhecer bem, até mais do que você, que já está comigo há 17 anos... Não a deixe ir embora da Colossus!",
  str_story_banner_2036 = "Explorar o Território Secreto exige muito <color=#FFB400>'MS'</color>, que é um tipo especial de substância. O <color=#FFB400>MS</color> representa quanto dele ainda resta.",
  str_story_banner_732 = "<color=#FFB400>MS</color> pode ser recuperado aqui com o tempo! Veja aqui mais detalhes!",
  str_story_banner_2037 = "PlayerName, as coordenadas do Território Secreto foram confirmadas. Vamos lá dar uma olhada!",
  str_story_banner_2038 = "PlayerName! Você está bem!? Desculpe, eu não consegui mirar nos sinais vitais de Nozard... Mas a essa altura, ele provavelmente não vai sobreviver, né?",
  str_story_banner_717 = "Em seguida, vamos voltar para uma altitude segura. Mesmo que não tenha perigo por ora, não podemos relaxar. Não podemos deixar ninguém sacrificar suas vidas.",
  str_story_banner_718 = "Diga a ela que a culpa não é dela. Se eu tivesse me aquecido mais rápido, esses Eclipsitas não teriam chance.",
  str_story_banner_719 = "Hum... Voar é um pouco difícil. O dano parece ser grave. Deixe-me procurar na área ao redor para ver se há lugares para coletar materiais de reparo.",
  str_story_banner_2020 = "PlayerName, a postura de voo de Soroz indica que ele está com dor. Acho que a batalha deve ter causado muitos danos.",
  str_story_banner_720 = "Hum? Espere, é uma nova fonte de sinal. O que Soroz encontrou?",
  str_story_banner_721 = "Eu agradeço a preocupação de Vice. Eu achei algo sim. É algum tipo de teste que pode nos dar <color=#FFB400>materiais de construção Colossus</color>. Por que não vamos dar uma olhada?",
  str_story_banner_2039 = "Desculpe por te atrapalhar, PlayerName. O dano causado pelas lutas é bem grave.",
  str_story_banner_730 = "Vou levar você a um lugar. Se conseguir reconstruí-lo, conseguirá me consertar.",
  str_story_banner_2040 = "Esse lugar não tinha vida. Mas as coisas mudaram agora. Você pode restaurá-lo à sua antiga glória.",
  str_story_banner_2041 = "Manter a Colossus e melhorar Aurorians exigem muitos recursos. A <color=#FFB400>Estação de Recursos</color> existe para achar mais recursos.",
  str_story_banner_2042 = "Agora construa uma <color=#FFB400>Estação de Recursos</color>.",
  str_story_banner_2043 = "Esse cômodo fará nossa coleção de recursos mais eficaz. Faça bom uso dele.",
  str_story_banner_2044 = "PlayerName, aí está você! Eu achei um novo teste. Talvez possamos pegar os materiais necessários para consertar Soroz!",
  str_story_banner_2045 = "A fonte de sinal está aqui, PlayerName!",
  str_story_banner_2046 = "Vice está esperando por você aqui. Descubra o que ela precisa!",
  str_story_banner_2047 = "Hum... PlayerName, você viu a Vice?",
  str_story_banner_2048 = "O Pilar Prisma... Ah, as memórias... Vamos consertar!",
  str_story_banner_2049 = [[
Muito bem, o <color=#FFB400>Pilar Prisma</color> foi reativado.
Vem dar uma olhada, PlayerName.]],
  str_story_banner_2050 = "Se tivermos os materiais, podemos melhorar o Pilar Prisma para aumentar sua eficiência de conversão de prisma!",
  str_story_banner_2051 = "Da mesma forma, atribuir Aurorians específicos também ajuda a melhorar a taxa de conversão do Pilar Prisma.\nVamos tentar!",
  str_story_banner_2052 = "Você não se esqueceu de como atribuir Aurorians, né? Tente gerenciar!",
  str_story_banner_2053 = "O sistema de missão parece que foi melhorado. Que tal dar uma olhada?",
  str_story_banner_2054 = "O Plugin Central só pode ser usado na ponte. Rápido, venha para a ponte!",
  str_story_banner_2055 = "Desafie os chefes do Desolation Codex para receber uma classificação, emblema de avatar e recompensas com base no dano causado.",
  str_story_banner_2056 = "Veja os requisitos de dano e as recompensas de todas as class. aqui.",
  str_story_banner_2057 = "Ao final de cada ciclo, recompensas e emblemas serão concedidos de acordo com sua classificação. Seu emblema será exibido em seu avatar pessoal como um símbolo de suas conquistas.",
  str_story_banner_2058 = "Agora, vamos desafiar o chefe deste ciclo!",
  str_story_banner_3001 = "Ascensão Aurorian vai desbloquear equipamento.\nDeixe-me mostrar como o <color=#FFB400>Equipamento Aurorian</color> funciona!",
  str_story_banner_3002 = "O equipamento de cada Aurorian é único. Eles podem <color=#FFB400>melhorar habilidades</color> e <color=#FFB400>aumentar poderes dos Aurorians</color>.",
  str_story_banner_3003 = "Além disso, o Equipamento Aurorian pode melhorar o efeito de <color=#FFB400>eficácias elementais</color>, melhorando as habilidades de Aurorians.",
  str_story_banner_3004 = "PlayerName! O Equipamento Aurorian também pode ser melhorado. É claro que custa um número bom de materiais especiais. Venha comigo e veja.",
  str_story_banner_3005 = "Não temos materiais suficientes agora!\nMas acredito que com PlayerName por perto, podemos conseguir!",
  str_story_banner_3011 = "Espere! Você notou o <color=#FFB400>ícone especial</color> acima do espaço da quinta equipe?",
  str_story_banner_3012 = "O ícone significa que você pode adicionar <color=#FFB400>Aurorians de Suporte</color> aqui!",
  str_story_banner_3013 = "Através de negociações, podemos convidar Aurorians fora da Colossus para ajudar na batalha! Eles são Aurorians de Suporte.",
  str_story_banner_3014 = "Você deve assinar um pacto com outras organizações para chamar Aurorians de Suporte. Há algumas organizações que estão dispostas a oferecer ajuda incondicional!",
  str_story_banner_3015 = "Não se pode usar Aurorians de Suporte em todo tipo de batalha. E o mesmo Aurorian de Suporte não pode ser atribuído mais de uma vez em um curto período.",
  str_story_banner_3016 = "Tudo bem, PlayerName! Você pode escolher o Aurorian de Suporte que achar melhor. O Aurorian de Suporte ocupará a quinta posição de formação.",
  str_story_banner_3017 = "Lembre-se de que <color=#FFB400>você não pode concluir certas Missões de Avaliação do Estágio com Aurorians de Suporte</color>!",
  str_story_banner_3018 = "<color=#FFB400>Você não pode concluir certas Missões de Avaliação do Estágio com Aurorians de Suporte</color>.",
  str_story_banner_3021 = "Recebemos uma mensagem de Illumina, PlayerName!",
  str_story_banner_3022 = "Deixe-me ver... Foi mencionado \"<color=#FFB400>Revenimento de Illumina</color>.\" Acho que já ouvi falar disso em algum lugar antes...",
  str_story_banner_3023 = "Será que são as ruínas recém-descobertas?\nO laboratório supostamente escavou muitos materiais que podem <color=#FFB400>melhorar equipamento</color>!",
  str_story_banner_3024 = "Vamos descobrir rapidinho!",
  str_story_banner_3031 = "A <color=#FFB400>Expedição</color> está pronta? Isso significa que conseguiremos dar apoio aos outros rapidamente!",
  str_story_banner_3032 = "Siga-me! Vamos ver a mesa de expedição!",
  str_story_banner_3033 = "Podemos ver todas as <color=#FFB400>Missões de Expedição</color> na mesa! Olhe ali.",
  str_story_banner_3034 = "A maioria das <color=#FFB400>Missões de Expedição</color> são emitidas por várias facções. Conclua a missão com Aurorians da mesma facção para obter mais recompensas!",
  str_story_banner_3035 = "Cada missão leva um tempo para concluir!\nComece a enviar seus Aurorians quando você se decidir!",
  str_story_banner_3036 = "Por que você não tenta agora, Navegador?",
  str_story_banner_3041 = "Oh! Esse cheiro familiar... Agora está bem fraco, mas eu já senti esse cheiro em Illumina antes!",
  str_story_banner_3042 = "Se não me equivoquei, isso é uma <color=#FFB400>Oficina</color> abandonada, né?",
  str_story_banner_3043 = "A Oficina é um local importante onde você pode criar muitos materiais.\nSeria um desperdício não usá-la.",
  str_story_banner_3044 = "Você vê a <color=#FFB400>fornalha</color> no centro? Cuidado, pode estar quente! \nVerifique o <color=#FFB400>painel</color> primeiro!",
  str_story_banner_3045 = "Não deixe os controles complicados te assustarem. É simples.",
  str_story_banner_3046 = "Lembre-se de que gasta <color=#FFB400>Reagentes Atômicos</color> para usar a fornalha. Reagentes Atômicos são produzidos aqui.",
  str_story_banner_3047 = "Melhore a Oficina para criar mais coisas!\nUm último lembrete: não brinque com fogo!",
  str_story_banner_3051 = "Navegador! Estou executando um plano que se chama “Operação Faça da Colossus a Nossa Casa”!\nVenha <color=#FFB400>decorar a Colossus</color> comigo!",
  str_story_banner_3052 = "Não me diga... Vai ter saias e gravatas-borboletas?",
  str_story_banner_3053 = "Mal posso esperar! Vou te familiarizar com o que precisa fazer para começar a decorar!",
  str_story_banner_3054 = "Vamos coletar todo tipo de Mobílias durante nossas aventuras.\nPodemos usá-las para decorar a Colossus!",
  str_story_banner_3055 = "Eu trouxe algumas coisas de outro lugar por enquanto. Vamos tentar primeiro!",
  str_story_banner_3056 = "Cada parte da mobília é diferente.\nAqui estão algumas instruções simples. Por que você não tenta?",
  str_story_banner_3057 = "Você tem que colocar a mobília no local certo. Mova-a meio centímetro para aquele lado, ok?",
  str_story_banner_3058 = "Ótimo! A mobília foi colocada! Mas ainda não acabou.\nVocê precisa <color=#FFB400>salvar</color> para manter as mudanças feitas.",
  str_story_banner_3059 = "Você percebeu? A mobília melhorou o <color=#FFB400>Ânimo</color> do cômodo!",
  str_story_banner_3060 = "É aqui que você pode ver o <color=#FFB400>Ânimo</color> da Colossus.",
  str_story_banner_3061 = "O Ânimo parece afetar todos! Então, também é dever do Navegador decorar a Colossus!",
  str_story_banner_3062 = "Isso é tudo sobre a “Operação Faça a Colossus tão Aconchegante Como uma Casa”! Mal posso esperar para ver toda a sua criatividade, Navegador!",
  str_story_banner_3063 = "Recebemos pactos novos! Agora podemos convidar Aurorians que não tinham se juntado a nós na Colossus para suporte temporário na batalha!",
  str_story_banner_3071 = "PlayerName! Venha comigo que eu vou te mostrar algo interessante!",
  str_story_banner_3082 = "Aparentemente, você pode recrutá-los ao concluir uma série de <color=#FFB400>missões especiais</color>!",
  str_story_banner_3083 = "Vamos ver os arquivos e <color=#FFB400>escolher qual Aurorian recrutaremos primeiro</color>!",
  str_story_banner_3084 = "Vejamos... O que precisamos fazer para concluir esse recrutamento?",
  str_story_banner_3086 = "Depois de concluir todas as missões da fase, a próxima fase será desbloqueada automaticamente. Se você concluir todas as missões, ganha esse Aurorian.",
  str_story_banner_3087 = "Mas lembre-se de que só as <color=#FFB400>missões</color> para o Aurorian <color=#FFB400>que está sendo recrutado</color> valerão. Não haverá progresso para Aurorians que não estão sendo recrutados agora!",
  str_story_banner_3091 = "Parece que esse desafio de recrutamento ficará sempre disponível. Lembre-se de checar seu progresso de missão de vez em quando!",
  str_story_banner_3092 = "Uma força misteriosa e poderosa nos espera à frente... Devemos ir e explorar?",
  str_story_banner_4000 = "Quando isso tudo vai acabar?",
  str_story_banner_4001 = "Não importa quanto tempo você tem, você nunca pode matar aquelas coisas chamadas Eclipsitas.",
  str_story_banner_4002 = "Isso me faz lembrar daquela mentira. Se eu puder vê-lo de novo, vou torrá-lo sem pensar.",
  str_story_banner_4003 = "Sempre tem alguém que acredita que vamos virar Eclipsitas, mas as mentes dessas pessoas são mais assustadoras do que os Eclipsitas.",
  str_story_banner_4004 = "O traidor está indo bem. Queria que ele tivesse morrido há muito tempo.",
  str_story_banner_4005 = "Talvez seja só eu, mas sinto que o traidor ainda vive.",
  str_story_banner_4006 = "Pena que a minha raiva não se manifestou, ou ele seria incinerado antes que a minha espada o acertasse.",
  str_story_banner_4007 = "Provavelmente Claymore decidiu que eu tinha mais chance de aguentar, então ele me cortou primeiro.",
  str_story_banner_4008 = "Esse é o começo de uma nova história? Espero que dessa vez com um final mais feliz.",
  str_story_banner_4009 = "Achei que seria melhor os Caçadores irem sozinhos, mas Frostfire e Regal sempre arranjam confusão quando eles vão.",
  str_story_banner_4010 = "Quem tende a perder o controle precisa de alguém racional para trazê-lo de volta ao caminho certo.",
  str_story_banner_4011 = "Talvez outros não entendam por que Claymore fez isso, mas não, eu não pretendo explicar isso pra ele. Eu só aceitei e registrei.",
  str_story_banner_4012 = "Nas histórias, aqueles que superam testes e aflições emergem alegremente.",
  str_story_banner_4013 = "Talvez tenhamos falhado em superar os testes idealizados para nós.",
  str_story_banner_4014 = "Na hora certa. Não importa quando, eu sempre tenho energia para matá-los.",
  str_story_banner_4015 = "Se você não aguenta, vire para o outro lado e não olhe. Eu não quero que você me critique como os outros pela forma como mato Eclipsitas.",
  str_story_banner_4016 = "Eu fui escolhido, treinado, e aceitei os poderes por vontade própria para erradicar todos eles. Então por que os Aurorians tentariam me impedir?",
  str_story_banner_4017 = "Acho que lembrei algo que preferia esquecer... Não, ainda não consigo.",
  str_story_banner_4018 = "Por que eu fiquei com ódio naquele momento?",
  str_story_banner_4019 = "Eles não querem que mencionem mais seus antigos nomes. Mas não sei por quê.",
  str_story_banner_4020 = "Não importa, não vou refletir algo tão profundo. Tudo que eu quero é caçar Eclipsitas como antes.",
  str_story_banner_4021 = "Mas não faça como meu antigo capitão, sacando uma espada e me apunhalando de repente! Isso não é certo!",
  str_story_banner_4022 = "O quê? Faz um longo tempo desde então? E o mundo não é o mesmo?",
  str_story_banner_4023 = "Eu não entendo.",
  str_story_banner_4042 = "Navegador! Encontramos algumas coisas interessantes enquanto consertávamos a Colossus.",
  str_story_banner_4043 = "Precisamos de materiais para consertar a sala.",
  str_story_banner_4044 = "Esse é um sistema de simulador de comandos que pode ajudar você a treinar. Ele cria diferentes situações de batalha, de acordo com as suas instruções.",
  str_story_banner_4045 = "Você ganha Pontos de Comando por concluir cenários de combate. Algumas batalhas também concedem fragmentos de dados.",
  str_story_banner_4046 = "Você pode escolher um disco de dados e começar agora mesmo!",
  str_story_banner_4047 = "A Sala de Simulação está pronta... Vamos descobrir como usá-la!",
  str_story_banner_4050 = "O fim! Maiden and the Ruins começou! Vamos ver o que há de novo neste evento.",
  str_story_banner_5001 = "Boas-vindas a uma nova aventura! Desbloqueie novas histórias e ótimos prêmios no evento <color=#FFB400>Destino do Nuvescer</color>!",
  str_story_banner_5002 = "Gaste Prismas em desafios da História Principal e Incursões: Recursos para obter <color=#FFB400>Pétalas de Nuvescer</color> para o evento. Desbloqueie cenários do evento e recompensas com as Pétalas de Nuvescer.",
  str_story_banner_5003 = "Descubra novas histórias! Desbloqueie-as com suas Pétalas de Nuvescer!",
  str_story_banner_5004 = "Múltiplas missões no evento. Complete mais missões para ter mais recompensas.",
  str_story_banner_5005 = "Use Pétalas de Nuvescer para <color=#FFB400>Sorteios</color>! <color=#FFB400>Ganhe um prêmio aleatório</color> da lista de presentes a cada sorteio.",
  str_story_banner_5006 = "Há 5 listas de presentes, cada uma com um grande prêmio. Desbloqueie a próxima lista ao ganhar o <color=#FFB400>grande prêmio</color>.",
  str_story_banner_5007 = "Quando mais Pétalas de Nuvescer tiver, mais recompensas ficam disponíveis!",
  str_story_banner_5008 = "Verifique as regras do evento para qualquer dúvida!",
  str_story_banner_5010 = "Permita-me apresentar-lhe o método de pesca.",
  str_story_banner_5011 = "Bem, isso é tudo que você precisa saber sobre a pesca. Agora, vamos começar o desafio!",
  str_story_banner_40301 = "Aí vem eles de novo! Fique perto de mim!",
  str_story_banner_40311 = "Não é minha culpa! Não é minha culpa!",
  str_story_banner_40321 = "Irmãzinha!",
  str_story_banner_40322 = "...",
  str_story_banner_40323 = "Os Eclipsitas estão indo na direção de Eve! Rápido, não podemos deixar Eve sofrer mais do que já sofreu!",
  str_story_banner_40324 = "Nem... pense em... machucar... minha irmã!",
  str_story_banner_501401 = "Afaste-se da minha irmã!",
  str_story_banner_501402 = "Sua irmã está fora de controle, e esta Cidade Baixa também!",
  str_story_banner_501403 = "Se não encontrarmos uma saída logo, seremos enterrados aqui...",
  str_story_banner_501404 = "Que Cidade Baixa? Não entendo nada do que você está dizendo!",
  str_story_banner_501405 = "Não nos culpe por sermos rudes se você vai continuar assim...",
  str_story_banner_501406 = "Nãoo... Gre... tel...",
  str_story_banner_501407 = "Desculpe, não tenho escolha... Rápido, vamos pegar o outro também!",
  str_story_banner_501501 = "Ei, meu amigo celestita. Fique de olho em nossos arredores para mim.",
  str_story_banner_501502 = "Espere o momento certo e escolha uma habilidade para avançar.",
  str_story_banner_501503 = "Vou fazer um esgotamento para explodir um pouco de areia. Isso ensinará uma lição aos inimigos próximos antes de avançarmos.",
  str_story_banner_501504 = "Isso é tudo. Fácil, certo?",
  str_story_banner_501505 = "Hmm... eles continuam vindo. Que irritante! No entanto, heh, o inimigo já está dentro do alcance.",
  str_story_banner_501506 = "Você quer jogar alguns brinquedos que serão realmente dolorosos de pisar?",
  str_story_banner_501507 = "Selecione uma habilidade para bombardear ou lançar mísseis no inimigo.",
  str_story_banner_501508 = "Aponte antes de jogar ou eu vou chutá-lo para fora do carro!",
  str_story_banner_501509 = "Fleur me disse que fez um pequeno dispositivo que poderia mudar Lumina.",
  str_story_banner_501510 = "Mas os Aurorianos não podem realmente ver o fluxo de Lumina, então eu ri da cara dele em resposta.",
  str_story_banner_501511 = "Olhando para trás, pode ter sido um presente para você.",
  str_story_banner_501512 = "Selecione a habilidade Airdrop. Escolha um local para lançar o airdrop lá.",
  str_story_banner_501601 = "Aham! W-Bem-vindo ao jogo <color=#FFB400>Bater e queimar</color>.\nSim, você, você aí... Ei! Por que a violência?",
  str_story_banner_501602 = "Posso ser um Eclipsita, mas não sou seu inimigo! Eu tenho uma tarefa es-especial para você:\n<color=#FFB400>Comande nossos camaradas Eclipsite!</color>\nPor que você está tão surpreso? Admita, você queria fazer isso há muito tempo, não é?",
  str_story_banner_501603 = "Até mesmo o lendário Eclipse <color=#FFB400>Senhor Augeano</color> está aqui para ajudar.\nNão há como perdermos desta vez!",
  str_story_banner_501604 = "Vamos, ajude-nos a <color=#FFB400>tirar o carro de corrida Rediesel Wrench</color> e vencer juntos!",
  str_story_banner_501605 = "Th-Isso aqui mostra o ATK e HP do inimigo,\ne direi que é uma maneira muito fácil de avaliar se você está à altura do desafio.",
  str_story_banner_501606 = "<color=#FFB400>Tocar em um inimigo auroriano mostra sua próxima ação.</color>",
  str_story_banner_501607 = "<color=#FFB400>Os aurorianos geralmente têm como alvo a unidade inimiga mais próxima.</color>",
  str_story_banner_501608 = "Mas eles <color=#FFB400>só podem se mover em blocos de seu próprio elemento!</color>\nMantenha distância e faça o possível para não deixar que nos machuquem.",
  str_story_banner_501609 = "Vamos entrar em ação!",
  str_story_banner_501610 = "Th-Isso é incrível!",
  str_story_banner_501611 = "Graças à habilidade especial de Lord Augean,\n<color=#FFB400>derrotar um auroriano renova nosso ACT, permitindo-nos agir mais uma vez.</color>",
  str_story_banner_501612 = "É tudo para você agora!",
  str_story_banner_501613 = "Uau! Chasm juntou-se à equipe!\nI-Ele vai explodir e levar o inimigo com ele!",
  str_story_banner_501614 = "Tudo bem, vamos ver o quão poderosa é sua explosão!",
  str_story_banner_501615 = "Abismo <color=#FFB400>causa dano em uma área em forma de diamante em torno de si.</color>\nIsso também <color=#FFB400>quebra o ladrilho em que está pisando.</color>",
  str_story_banner_501616 = "Olha, os Longhooks também se juntaram à batalha!",
  str_story_banner_501617 = "Espere um minuto. Por que esses caras parecem estar em transe?\nSeus ganchos não chegam nem perto do normal.",
  str_story_banner_501618 = "<color=#FFB400>Eles podem prender e arrastar alvos em até 3 blocos na frente deles.</color>",
  str_story_banner_501619 = "Mesmo assim,\nem certas circunstâncias, <color=#FFB400>fisgar outros Eclipsites pode ajudar a mudar as coisas.</color>",
  str_story_banner_501620 = "Aqui vai uma dica para você. Depois que todos os nossos Eclipsites concluírem seus movimentos,\n<color=#FFB400>Aurorianos atacarão a unidade inimiga mais próxima.</color>\nQuando vários Eclipsites estão próximos, <color=#FFB400>eles terão como alvo aquele com o HP mais baixo.</color>",
  str_story_banner_501621 = "Mesmo quando há outros Eclipsites dentro do alcance,\nos aurorianos caçarão incansavelmente o mais próximo. A-Aurorianos são um bando assustador...",
  str_story_banner_501622 = "Mas você pode usar essa característica contra eles! Ao sacrificar um companheiro de equipe,\nvocê pode permitir que outros Eclipsites se aproximem deles.",
  str_story_banner_501630 = "Atenção, PlayerName. A atmosfera aqui não parece certa.",
  str_story_banner_501631 = "Esses monstros em particular são apenas de aparência estranha.",
  str_story_banner_501632 = "As regras do Sistema de Sanidade são aplicadas a esta batalha. Quando a Sanidade cai, os efeitos correspondentes são acionados.",
  str_story_banner_501633 = "Alguns aurorianos parecem ser capazes de afetar a batalha de maneira semelhante. Seus efeitos de habilidade também são afetados por pontos de sanidade.",
  str_story_banner_501634 = "Lembrar. Fique calmo e lide com a situação com calma.",
  str_story_banner_501635 = "Parece que existem regras de batalha adicionais.",
  str_story_banner_502701 = "PlayerName, a batalha aqui vai ser um pouco diferente.",
  str_story_banner_502702 = "Veja o <color=#FFB400>contagem regressiva</color> lá?",
  str_story_banner_502703 = "É um temporizador que exibe dia e noite. Quando a contagem regressiva terminar, o dia e a noite serão trocados.",
  str_story_banner_502704 = "Este Eclipse não está se movendo, mas...",
  str_story_banner_502705 = "Minhas flechas não estão machucando nada?!",
  str_story_banner_502706 = "Deixe-me ver se há alguma coisa no manual sobre este Eclipse...",
  str_story_banner_502707 = "Ah! De acordo com o manual, este Eclipsite é enfraquecido durante o dia e entra em estado defensivo.",
  str_story_banner_502708 = "Durante esse período, ele parará de atacar e se concentrará na defesa, evitando a maioria dos ataques.",
  str_story_banner_502709 = "E só pode ser danificado por <color=#FFB400>ataques de grande área</color>!",
  str_story_banner_502710 = "Vamos mudar o Capitão e derrotá-lo com um ataque de grande área!",
  str_story_banner_502711 = "PlayerName, dia e noite mudaram.",
  str_story_banner_502712 = "Parece que o Eclipse também está mudando. Está começando a se mexer!",
  str_story_banner_502713 = "Cuidadoso, PlayerName!",
  str_story_banner_502714 = "Eu deixo o resto com você!",
  str_story_banner_502801 = "O que um Eclipsite de alto nível está fazendo aqui?",
  str_story_banner_502802 = "Não há nada no manual sobre como lidar com um Eclipsite...",
  str_story_banner_502803 = "Acho que nossas mãos estão amarradas. Teremos que encontrar uma maneira de sair daqui!",
  str_story_banner_502804 = "Olhar, PlayerName, acho que essa é a saída!",
  str_story_banner_502805 = "Parece que vai desmoronar a qualquer momento. Vamos correr para isso!",
  str_story_banner_502806 = "Não deixe aquele Eclipsite derrubar a saída!",
  str_story_banner_502901 = "Essa coisa... Mudou!",
  str_story_banner_502902 = "Parece que ficou mais forte também...",
  str_story_banner_502903 = "Assista, PlayerName.",
  str_story_banner_503001 = "Este cheiro desagradável... O que é?",
  str_story_banner_503002 = "Meu poder é enfraquecido quando me aproximo.",
  str_story_banner_503003 = "Por favor, tente evitá-lo, se possível.",
  str_story_banner_5016411 = "Lenore viu você chegando, PlayerName. Os Eclipsites à distância representam uma séria ameaça.",
  str_story_banner_5016412 = "Deixe Lenore terminar todos de uma vez. Em caso de insuficiência <color=#FFB400>Pontos de sanidade</color>, <color=#FFB400>HP</color> pode ser deduzido em seu lugar.",
  str_story_banner_5016413 = "Bom trabalho, PlayerName.",
  str_story_banner_5016414 = "Os Eclipsites restantes estão espalhados por todo o lugar, mas tudo bem. Lenore fica mais forte quando <color=#FFB400>sanidade cai para 0</color>.",
  str_story_banner_5016415 = "PlayerName, por favor, guie Lenore para liberar um Chain Combo e acabar com os Eclipsites restantes.",
  str_story_banner_5016416 = "Hum? Miragens? Normalmente eles não aparecerão até que nossa <color=#FFB400>Sanity</color> esteja bem baixa. Ahahah! Podemos entrar em colapso em breve.",
  str_story_banner_5016417 = "Bocejo... Essas criaturas irritantes não passam de isca.",
  str_story_banner_5016418 = "Uma sensação maravilhosa... Essa força misteriosa... Hahah! Vamos matá-los todos!",
  str_story_banner_5016419 = "Noite Branca lá no alto... Onde estou? Estou com uma enorme dor de cabeça... Já ficamos sem <color=#FFB400>sanidade</color> já?",
  str_story_banner_5016420 = "Ahahah! Não se preocupe. Eu posso ajudar a aliviar sua dor.",
  str_story_banner_5016421 = "Se sentindo melhor? Deixe-me ajudar a restaurar um pouco de <color=#FFB400>Sanity</color>, se necessário.",
  str_story_banner_50303 = "Parece que temos todos os materiais necessários. Chubb!",
  str_story_banner_50402 = "Esta é a bancada de trabalho da Hyacinth Tower. Aqui, você pode construir todos os tipos de edifícios e móveis. Chubb!",
  str_story_banner_50602 = "Parece que quatro aurorianos podem se estabelecer aqui, e os aurorianos estabelecidos também melhorarão sua afinidade! Tente convidar a Sra. Blanc!",
  str_story_banner_50701 = "Aqui, você pode ver o nível Cloud Gardens.",
  str_story_banner_50801 = "Há tantos peixes no rio! Vamos começar a pescar!",
  str_story_banner_50804 = "Pegamos um peixe! Apresse-se e enrole-o!",
  str_story_banner_50901 = "Bem-vindo à Loja Cloud Gardens, Chubb! Aqui, você pode trocar mercadorias e concluir pedidos para ganhar fragmentos de rocha do Cloud Gardens, Chubb!",
  str_story_banner_51001 = "Chubb, Chubb! Eu vou te ensinar como plantar uma árvore!",
  str_story_banner_9001 = "Chubb, Chubb!",
  str_story_banner_9002 = "Por favor, colete madeira primeiro, Navegador!",
  str_story_banner_9003 = "Madeira, madeira. Chubb, Chubb!",
  str_story_banner_9004 = "Parece que precisamos de mais minérios...",
  str_story_banner_9005 = "Minério, minério. Chubb, Chubb!",
  str_story_banner_9006 = "Temos todos os materiais! Deixe-me cuidar disso, Chubb!",
  str_story_banner_9007 = "Vamos tentar construir um dormitório Gardens em Hyacinth Tower!",
  str_story_banner_9008 = "Vamos colocar o dormitório!",
  str_story_banner_9009 = "Vamos convidar a Sra. Blanc para se mudar para o dormitório agora!",
  str_story_banner_9010 = "Vá falar com a Sra. Blanc e dê as boas-vindas a ela!",
  str_story_banner_9011 = "Olá, Navegador. Parece Vice tem algo para lhe dizer.",
  str_story_banner_9012 = "Você pode pescar ao meu lado. De uma chance!",
  str_story_banner_9013 = "Hora de pescar e relaxar, Navegador.",
  str_story_banner_9014 = "Depois de reunir todos os materiais, vá para Chubb e conserte a loja!",
  str_story_banner_9015 = "Parece que alguém está esperando por você lá na loja, Navigator.",
  str_story_banner_9016 = "Envie um pedido para o Comerciante Chubb!",
  str_story_banner_9017 = "Você concluiu o pedido, Navegador?",
  str_story_banner_9018 = "Encomenda completa! Falar com Vice agora!",
  str_story_banner_9019 = "Vá para a Hyacinth Tower e construa um terreno de Land of Fertility!",
  str_story_banner_9020 = "Coloque a Terra da Fertilidade em um terreno baldio!",
  str_story_banner_9021 = "Vamos tentar criar e colher uma Árvore Única!",
  str_story_banner_9022 = "Depressa, vá procurar um local adequado para recuperar!",
  str_story_banner_503501 = "Uma vitória completa, PlayerName!",
  str_story_banner_503502 = "Enquanto era uma emergência, conseguimos sair dela sem um arranhão!",
  str_story_banner_503503 = "PlayerName?",
  str_story_banner_503504 = "C-Carleen! PlayerName...",
  str_story_banner_503505 = "... também não me respondeu.",
  str_story_banner_503506 = "Se você pode nos sentir, PlayerName, responda agora!",
  str_story_banner_503507 = "PlayerName...!",
  str_story_banner_503601 = "Se bem me lembro, este é o caminho para o Núcleo Central.",
  str_story_banner_503602 = "Um grande número de Eclipsitas invadiu a Torre do Retorno.",
  str_story_banner_503603 = "Seria difícil derrotá-los todos em nossa situação atual.",
  str_story_banner_503604 = "Mas não deve ser difícil simplesmente escapar deles.",
  str_story_banner_504001 = "Os estágios do Modo Caixa de Pandora são mais difíceis do que o Modo Normal. Por favor, esteja pronto.",
  str_story_banner_504002 = "Ao mesmo tempo, o Modo Caixa de Pandora tem condições especiais completas que exigem que várias equipes cooperem.",
  str_story_banner_5017311 = "É quase como um estágio de sobrevivência. As ondas de monstros parecem intermináveis...",
  str_story_banner_5017312 = "Isso soa como Barton! Gronru, você ouviu isso?",
  str_story_banner_5017313 = "Acho que sim... ele está bem?",
  str_story_banner_5017314 = "Se for ele... Não precisa se preocupar.",
  str_story_banner_5017315 = "Aquela coisa que eu estava falando com você. Você descobriu alguma coisa?",
  str_story_banner_5017316 = "Bem, de acordo com minhas experiências claras de estágio...",
  str_story_banner_5017317 = "Isso não é um jogo!",
  str_story_banner_5017318 = "Vai tudo ficar bem. A julgar pelos padrões desses Eclipsites, não sobrarão muitos.",
  str_story_banner_5017319 = "Se for esse o caso, vamos derrubá-los todos.",
  str_story_banner_5017320 = "Vou enviar-lhe as suas posições e ajudá-lo.",
  str_story_banner_5017321 = "É hora de brilhar, Lança Perfuradora de Estrelas!",
  str_story_banner_5017322 = "Há um monte de Eclipses aqui! Eu me pergunto se o Grande Marechal está bem. Provavelmente não precisamos nos preocupar.",
  str_story_banner_5017323 = "Oh, você me cercou. Eu gosto dessas probabilidades. Hora de experimentar meu novo brinquedo!",
  str_story_banner_5017324 = "Isso é incrível! Enquanto continuarmos lutando, nosso poder continuará crescendo...",
  str_story_banner_5017325 = "Vai! Vai!",
  str_story_banner_5018311 = "Tantos eclipses estão no caminho! My Secret Trove vai cuidar disso.",
  str_story_banner_5018312 = "Isso é mais do que eu pretendia. Deixe-me pegar meu guarda-chuva de volta e acabar com os Eclipsitos restantes.",
  str_story_banner_5018321 = "Hum... O inimigo está um pouco longe de mim... Manae, vou deixar isso para você.",
  str_story_banner_5019301 = "Há mais inimigos chegando, vamos fazer isso!",
  str_story_banner_5019302 = "Agora é a hora! Use o <color=#FFB400>Habilidade especial</color>!",
  str_story_banner_5019303 = "Existem muitos inimigos da floresta. Mude o capitão agora e ensine-lhes uma lição!",
  str_story_banner_5020301 = "Parece que não há rota para nos movermos para o monstro e atacar.",
  str_story_banner_5020302 = "Isso não vai me parar! O Míssil Flecha Solar deste mecha dinâmico pode abrir um caminho. Experimente agora!",
  str_story_banner_5020303 = "Os obstáculos foram removidos! Acabe com eles de uma vez!",
  str_story_banner_5020311 = "Que erro de cálculo! Na verdade, fiquei magoado com as táticas de multidão dos Eclipsites.",
  str_story_banner_5020312 = "Você não pode ser pego em uma guerra de atrito com esses Eclipsites. Você deve curar suas feridas e sair o mais rápido possível.",
  str_story_banner_5020313 = "Você ainda pode lançar Combust mais algumas vezes. Pegue o curativo e junte-se a todos os outros rapidamente.",
  str_story_banner_5020314 = "Muito bom. Depois de obter as bandagens restantes através do Combust, você deve ser forte o suficiente para derrotar todos os inimigos. Vamos lá, seus Eclipsitas não-bons!",
  str_story_banner_5020321 = "O-que lugar é esse?",
  str_story_banner_5020322 = "Cuidado, devemos ter sido arrastados para um espaço que a antiga arma da civilização criou.",
  str_story_banner_5020323 = "É este o \"tempo de confronto\" que acabou de mencionar?",
  str_story_banner_5020324 = "Deve ser. Se prepare!",
  str_story_banner_5020325 = "Vamos lá. Esta é a última batalha!",
  str_story_banner_5020326 = "Prometi a Elvis cumprir seu desejo e reativar a Pedra do Vento.",
  str_story_banner_5020327 = "Vocês feras! Nem pense em dar um passo mais perto!",
  str_story_banner_5020328 = "Elvis, como está indo do seu lado?",
  str_story_banner_50213211 = "Embora tudo seja para os animais maravilhosos, você não acha que as coisas têm sido muito difíceis? O que você acha, Kylo?",
  str_story_banner_50213212 = "Lo...",
  str_story_banner_50213213 = "Sim! Mas devo ter sucesso desta vez para impressionar meu mestre!",
  str_story_banner_50213214 = "Lo!",
  str_story_banner_50213215 = "Uau! De repente, há tantos Eclipsites!",
  str_story_banner_50213216 = "Oh, Kyllo deve estar ficando com fome em breve. Acabe com eles rapidamente para que possamos voltar e fazer um banquete!",
  str_story_banner_50213217 = "Lo!",
  str_story_banner_50213218 = "O que é isso? Por que uma marca de caça está lá? Que estranho. Poderia ter caído por acidente quando eu estava jogando no Soroz? Oh bem, é melhor assim. Vamos, Kylo!",
  str_story_banner_50213219 = "Nós causamos alguns estragos, não foi, Kyllo!",
  str_story_banner_50213220 = "Lo! Lo!",
  str_story_banner_50213221 = "A água foi borrifada em todos os lugares... Bem, ainda parece haver muitos Eclipsitas. Vamos colocar algumas Marcas de Caça!",
  str_story_banner_50213222 = "De repente, tenho uma ideia divertida! Kyllo, vamos cobrar!",
  str_story_banner_50213311 = "Está tão quente! Você quer se refrescar?",
  str_story_banner_50213312 = "Você vê os Eclipses ali? Eles estão na minha marca Sunshower. Deixe-me ativá-lo para criar uma primavera refrescante!",
  str_story_banner_50213313 = "Os Eclipsites foram lançados no ar! Tralala!",
  str_story_banner_50213314 = "Olhar! Uma nova marca aparecerá em um ladrilho que tenha 3 Marcas de Chuva de Sol ao seu redor.",
  str_story_banner_50213315 = "Excelente! Vamos derrotar os inimigos com minha pistola de água agora em uma luta de pistola de água!",
  str_story_banner_50213401 = "Muitos Eclipsites apareceram no teatro sem nome durante uma apresentação magnífica! Ninguém sabia dizer se isso era uma ilusão causada pela perda gradual de sanidade ou uma ameaça real, mas Jeno não parecia ser afetado de forma alguma no palco.",
  str_story_banner_50213402 = "Vamos dar as boas-vindas ao nosso estimado convidado, PlayerName, para usar o Deck de Origem comigo no palco!",
  str_story_banner_50213403 = "Ao mesmo tempo, também quero convidar Paloma, nossa outra convidada de hoje!",
  str_story_banner_50213404 = "Aurorianos ou Eclipsitas, todos vieram me apoiar!",
  str_story_banner_50213405 = "No início, havia apenas luz. Então, havia o sol, a lua e as estrelas. Quando sua luz suave é lançada sobre as cartas, dá origem a todas as coisas. Daí o nome \"Origem\".",
  str_story_banner_50213406 = "Agora é a hora de mostrar seu poder.",
  str_story_banner_50213407 = "Primeiro, precisamos obter muitos cartões. Cuidado, aqueles que desejam espionar os segredos da Origem podem perder a sanidade...",
  str_story_banner_50213408 = "Mais um cartão. Só vou perder um pouco mais de sanidade.",
  str_story_banner_50213409 = "Mais! Eu posso levar mais do que isso.",
  str_story_banner_50213410 = "Esta é a biblioteca. O número de cada tipo de cartão é mostrado aqui.",
  str_story_banner_50213411 = "Vá aqui para entrar na tela de seleção do Deck de Origem.",
  str_story_banner_50213412 = "As cartas Solar, Lunar e Cósmica à esquerda podem ser arrastadas para os slots de cartas. Um efeito correspondente será acionado quando os Origin Cards forem colocados em todos os 3 slots.",
  str_story_banner_50213413 = "Agora, selecione 1 cartão de cada tipo e coloque-os nos slots de cartão.",
  str_story_banner_50213414 = "A combinação Astronomical Transit é formada quando todas as 3 cartas são de tipos diferentes, o que aumenta permanentemente o ATK do membro na parte de trás da equipe.",
  str_story_banner_50213415 = "PlayerName, por favor, faça de Paloma a capitã.",
  str_story_banner_50213416 = "Agora entre na tela de seleção do Deck de Origem.",
  str_story_banner_50213417 = "Vamos formar a combinação Luminous Cluster desta vez. Coloque 3 cartões do mesmo tipo nos slots de cartão.",
  str_story_banner_50213418 = "Paloma agora pode receber 2 efeitos de combinação do Deck de Origem, o que aumentará muito seu poder de combate. É nisso que eu me supero.",
  str_story_banner_50213419 = "Há mais 1 combinação. Lembre-se de usá-lo quando quiser recuperar sua sanidade.",
  str_story_banner_50213420 = "PlayerName, o palco agora é seu. Continue o show com qualquer desempenho que você desejar.",
  str_story_banner_507401 = "Calma, Casta!",
  str_story_banner_507402 = "Você está falando sério para eu me acalmar com o assassino de Matilda bem na minha frente?!",
  str_story_banner_507403 = "Eu vou dizer isso uma última vez, saia do meu caminho!",
  str_story_banner_507404 = "Parece que vamos ter que fazer isso da maneira mais difícil...",
  str_story_banner_50223211 = "Atenção! Um Eclipse está nos emboscando ali.",
  str_story_banner_50223212 = "Deixe-me preparar minhas armas, então podemos chegar mais perto e surpreendê-los com o que temos.",
  str_story_banner_50223213 = "Ladrilhos verdes e ladrilhos aprimorados podem me ajudar a encontrar os pontos fracos do inimigo. Para cada 6 pontos encontrados, meu ataque seguinte se tornará mais poderoso.",
  str_story_banner_5022321301 = "Se um ladrilho atender a ambas as condições, posso encontrar o dobro dos pontos fracos, então tente se mover ao longo do caminho de ambos os ladrilhos.",
  str_story_banner_50223214 = "Limite de pontos de gatilho atingido! As armas estão quentes novamente. Use sua habilidade ativa novamente e elimine os monstros ao redor!",
  str_story_banner_50223111 = "Ainda há tantos inimigos, mas eles ainda não estão ao alcance do meu Heavy Fire...",
  str_story_banner_50223112 = "Sem uma linha de ataque clara, não há muito que eu possa fazer.",
  str_story_banner_50223113 = "Heh... Se não houver linha de ataque, teremos que fazer uma nós mesmos! Expansão da bala!",
  str_story_banner_50223114 = "O inimigo não tem para onde correr! Hora de acabar com eles com meu Heavy Fire!",
  str_story_banner_41000111 = "De acordo com a inteligęncia... Esta deveria ser a cidade subterrânea-Achoo! Ninguém parece ter vindo aqui há algum tempo, então tenha cuidado ao explorar.",
  str_story_banner_41000112 = "Está tão bem escondido. Teríamos muita dificuldade em encontrá-lo se Siobhan não estivesse aqui.",
  str_story_banner_41000113 = "Acho que cheiro algo nojento! Miau!",
  str_story_banner_41000114 = "Ei! Os Eclipsites aqui parecem ter dominado uma nova habilidade estranha!!!",
  str_story_banner_41000115 = "É um Wormgate. Foi assim que eles vieram e atacaram a cidade subterrânea.",
  str_story_banner_41000116 = "Parece perigoso, miau.",
  str_story_banner_41000117 = "Parece que os Eclipsites continuam emergindo dele, então temos que ser cautelosos.",
  str_story_banner_41000121 = "Um, dois... Tem muita coisa vindo.",
  str_story_banner_41000122 = "Vamos encontrar um terreno favorável antes que eles apareçam.",
  str_story_banner_41000123 = "Vamos lá juntos primeiro!",
  str_story_banner_41000131 = "Ainda bem que viemos aqui, senão estaríamos cercados por aqueles Eclipsitas.",
  str_story_banner_41000132 = "Há muitos Eclipses. Precisamos combatê-los e descobrir uma saída.",
  str_story_banner_41000133 = "Que comece a batalha!",
  str_story_banner_41000141 = "Ahhh! Minha garganta!",
  str_story_banner_41000142 = "É este... o gás nocivo mencionado no contrato?",
  str_story_banner_41000143 = "Não se preocupe. Ainda há muito tempo até que nos enlouqueça.",
  str_story_banner_41000151 = "Acho que vejo uma saída.",
  str_story_banner_41000152 = "De acordo com o projeto anterior, esse caminho deve levar a uma sala com um dispositivo de ventilação!",
  str_story_banner_41000161 = "Não parece que o caminho à frente vai ser fácil de passar...",
  str_story_banner_41000162 = "Este é o momento perfeito para trazer à tona PlayerNameo mais novo equipamento! Miau!",
  str_story_banner_41000163 = "Caltrops furiosos!",
  str_story_banner_41000164 = "Você realmente trouxe isso. Eu estava pensando em estudar mais tarde...",
  str_story_banner_41000165 = "Aham... De qualquer forma, vamos PlayerName use-o para mudar o Lumina. Nós vamos correr todo o caminho até lá em uma respiração!",
  str_story_banner_41000171 = "PlayerName, é bastante simples de usar. Basta jogá-lo, miau! Até Revy pode usá-lo corretamente!",
  str_story_banner_41000172 = "Fico feliz em ouvir isso.",
  str_story_banner_41000173 = "O que você quer dizer com \"até Revy pode usá-lo corretamente\" ...",
  str_story_banner_41000181 = "Parece que está funcionando! Agora, PlayerName, precisamos de você para nos guiar!",
  str_story_banner_41000211 = "Deixe o resto conosco, Vice.",
  str_story_banner_41000212 = "Tudo bem, eu estou confiando em você para proteger PlayerName.",
  str_story_banner_41000213 = "Relaxe, tudo deve ficar bem com o oficial de tecnologia Gronru e Migard aqui. Vocês descansem por enquanto.",
  str_story_banner_41000214 = "Aviso. Pedra estranha detectada nas proximidades.",
  str_story_banner_41000215 = "Essa deve ser a Pedra Halo... Mas o que ela está fazendo aqui? Não deveria estar trancado no nível mais baixo do Laboratório de Pesquisa?",
  str_story_banner_41000216 = "Será que alguém já esteve aqui?",
  str_story_banner_41000217 = "Isso é impossível. Provavelmente foi trazido aqui sem querer por um Eclipsite. Sem alguém para comandá-los, eles apenas se movem e agem indiscriminadamente.",
  str_story_banner_41000221 = "Bem, que bom que eles estão aqui. Hehe, vamos ativar essa coisa!",
  str_story_banner_41000231 = "Parece bastante útil. Ao produzi-lo em massa, poderíamos resolver muitos dos nossos problemas no campo de batalha...",
  str_story_banner_41000232 = "Desculpe informar, Chefe, mas acho que ainda está nas fases iniciais da pesquisa. Como relíquia da antiga civilização, é um pouco instável.",
  str_story_banner_41000233 = "Isso mesmo! Percebi que se o Lumina for muito complexo, ele falha!",
  str_story_banner_41000241 = "Aviso. Inimigos se aproximando.",
  str_story_banner_41000242 = "Nós realmente não podemos fazer uma pausa, podemos?",
  str_story_banner_41000243 = "Force-os de volta por enquanto! Todos, ataquem!",
  str_story_banner_41000251 = "Aviso. Pedra desagradável detectada.",
  str_story_banner_41000252 = "Já sabemos disso. Você vai se repetir todas as vezes?",
  str_story_banner_41000253 = "Essa pedra parece estar suprimindo nossas habilidades... Preste muita atenção nisso, PlayerName!",
  str_story_banner_41000261 = "Confirmado. Incapaz de usar certas habilidades.",
  str_story_banner_41000262 = "É verdade...",
  str_story_banner_41000263 = "Se isso fosse algum tipo de jogo, nossa melhor jogada seria fugir dele!",
  str_story_banner_41000271 = "Sinto-me muito melhor agora. Até o ar parece muito mais claro.",
  str_story_banner_41000272 = "Mas com essa pedra bloqueando o caminho, vamos ter dificuldade em fazer qualquer progresso.",
  str_story_banner_41000273 = "Interessante. Aqui, deixe-me tentar algo.",
  str_story_banner_41000281 = "Uau! Parece que enquanto estivermos fora de sua área de efeito, nossos poderes não serão afetados!",
  str_story_banner_41000282 = "De fato. Fiz questão de manter uma certa distância dele agora antes de atacar.",
  str_story_banner_41000291 = "Lá!",
  str_story_banner_41000292 = "Parece que este caminho leva a um ventilador. Estamos prestes a passar por este andar!",
  str_story_banner_41000293 = "Suspiro... Você poderia parar de tratar a batalha como se fosse um jogo? Deixa para lá. PlayerName, por favor, leve-nos até lá rapidamente.",
  str_story_banner_11200202 = "PlayerName, recebemos um pedido da Federação Illumina para investigar Undercity π.",
  str_story_banner_11400101 = "O Laboratório de Axelia começou! Colete peças de sucata e ajude Axelia a completar seus experimentos!",
  str_story_banner_11500401 = "Navigator, um ninho apareceu perto do Território Secreto, e um grande número de Eclipsites foi avistado. Devemos lidar com eles o mais rápido possível!",
  str_story_banner_11500701 = "Navegador! Um enorme enxame de Eclipsites apareceu! A única maneira de sairmos vitoriosos aqui hoje é se repelirmos todas as ondas do Eclipsite!",
  str_story_banner_11500702 = "Limpamos a primeira onda de Eclipsites! Cada vez que você lutar contra uma onda de Eclipsites, você receberá uma Relíquia como recompensa para fortalecer seu poder de combate nas batalhas seguintes. Agora, selecione uma Relíquia!",
  str_story_banner_11500703 = "Você derrotou o chefe! Um novo companheiro pode se juntar à sua equipe para ajudá-lo na batalha. Agora, selecione um auroriano!",
  str_story_banner_11500704 = "Um auroriano que se juntar a você na batalha pode conectar peças para lutar, lançar Chain Combos e usar habilidades ativas, assim como o resto de sua equipe.",
  str_story_banner_11500705 = "Você só pode avançar depois de eliminar Eclipsites suficientes!",
  str_story_banner_11500706 = "Esta será uma luta difícil... Mas não se preocupe - nesta batalha, você terá poderosos companheiros aurorianos para ajudá-lo a sair vitorioso!",
  str_story_banner_11500707 = "Agora, é hora de se preparar para lutar!",
  str_story_banner_523500201 = "É hora de relatar a Dona Nina. Tudo está indo bem com a casa mal-assombrada por enquanto.",
  str_story_banner_523500202 = "Eu me pergunto como a senhorita Nina tem passado recentemente? Sanae deveria estar cuidando bem dela.",
  str_story_banner_523500203 = "Hmm... Eclipsites, que criaturas patéticas. É uma pena que não tenho tempo para colocá-los para dormir agora.",
  str_story_banner_523500204 = "Um mordomo perfeito nunca deve se atrasar. Devo me apressar.",
  str_story_banner_523500301 = "Fazendo-me ir ao subúrbio para encontrar uma carteira perdida ou algo assim - por que Dayna ainda me trata como uma criança?",
  str_story_banner_523500302 = "A carteira... A carteira... Ah! Aqui está!",
  str_story_banner_523500303 = "Hehe, eu deveria pedir a ela outra tarefa depois que eu voltar. Eu me tornarei um verdadeiro espadachim um dia se continuar assim!",
  str_story_banner_523500304 = "O que!!?? Quando tantos Eclipses apareceram atrás de mim?!",
  str_story_banner_523500305 = "Está bem! Sadie! Faça o que você costuma fazer durante o treino... Faça o que você costuma fazer durante o treino... Faça o que você costuma fazer durante o treino...",
  str_story_banner_523500306 = "Bola aérea-!",
  str_story_banner_523500307 = "Funcionou! Estou a um passo de me tornar um fanfarrão! Vou cuidar de você rapidamente e contar a Dayna tudo sobre minha jogada legal!",
  str_story_banner_523500101 = "É hora de relatar a Dona Nina. Tudo está indo bem com a casa mal-assombrada por enquanto.",
  str_story_banner_523500102 = "Uau! O que há de errado com este lugar? Por que de repente há Eclipses ao meu redor? Isso é assustador!",
  str_story_banner_523500103 = "Fique calmo... Olha, tem outro conjunto deslumbrante ali.",
  str_story_banner_523500104 = "Posso me teletransportar para lá primeiro, ajustar minha posição e destruí-los!",
  str_story_banner_523500105 = "Tada! Assista minha entrada deslumbrante!",
  str_story_banner_523500106 = "Este caminho nos permite mover-se entre duas matrizes deslumbrantes. Vamos convocar uma nova matriz deslumbrante enquanto atacamos os Eclipsites e conectar essas duas matrizes deslumbrantes.",
  str_story_banner_523500107 = "A matriz deslumbrante tornou-se maior. Vamos destruir esses Eclipsites aterrorizantes agora.",
  str_story_banner_524300101 = "Isto é mau! Não só as tropas estão separadas, como também temos Eclipsites.",
  str_story_banner_524300102 = "Vamos chamá-lo apenas de uma mudança de humor.",
  str_story_banner_524300103 = "Axélia, é a sua vez!",
  str_story_banner_524300104 = "Cópia de. Ativando o Módulo de Autoridade. Rota ideal calculada.",
  str_story_banner_524300105 = "Vou compensar qualquer falta de cura e poder de fogo.",
  str_story_banner_524300106 = "Em espera, Grande Marechal.",
  str_story_banner_10130701 = "Acho que já chegamos a uma conclusão!",
  str_story_banner_10130702 = "O simulador tem um desempenho muito além das nossas expectativas!",
  str_story_banner_10130703 = "PlayerName parece ter ficado mais forte.",
  str_story_banner_10130704 = "Isso só pode ser confirmado depois PlayerName desconecta do Colossus e termina o experimento.",
  str_story_banner_10130705 = "Afinal, ainda precisamos verificar os dados de suas funções físicas.",
  str_story_banner_10130706 = "Silvo-!!!",
  str_story_banner_10130707 = "Como isso é possível?!",
  str_story_banner_10130708 = "T-Os dados do antigo campo de batalha devem estar corrompidos!",
  str_story_banner_10130709 = "Pesquisadores, ouçam-me! Encerre o experimento imediatamente!",
  str_story_banner_10131201 = "Sentindo tremores do chão.",
  str_story_banner_10131202 = "A próxima desintegração tocará o manto, deslocando e rachando a superfície.",
  str_story_banner_10131203 = "O campo de batalha virtual está prestes a atingir seu ponto sem retorno.",
  str_story_banner_10131204 = "Farei a contagem final para você.",
  str_story_banner_524300201 = "Huff... Os Eclipsites continuam chegando. Eles estão apenas tentando me desgastar? E eu estou ferido...",
  str_story_banner_524300202 = "Mas não serei derrotado por suas táticas.",
  str_story_banner_524300203 = "Escolha o caminho mais longo que você pode viajar para que eu possa perfurar seus corpos com Australis Spears primeiro.",
  str_story_banner_524300204 = "Os preparativos preliminares foram concluídos. Iniciando o tratamento.",
  str_story_banner_525300201 = "*Boceja* Parece que temos Eclipsites chegando.",
  str_story_banner_525300202 = "Aquele Eclipsite de elite está protegendo-os de serem destruídos.",
  str_story_banner_525300203 = "Heh... Você acha que está seguro se escondendo lá?",
  str_story_banner_525300204 = "Ataque! Todo o mundo! Mate aquele Eclipsite de elite primeiro!",
  str_story_banner_525400301 = "Oh! Lola, prometo acompanhá-la durante todo o seu treinamento especial, desde que você compartilhe todas as últimas fofocas comigo!",
  str_story_banner_525400302 = "Muitíssimo obrigado! Dê-me um pote do meu mel favorito também!",
  str_story_banner_525400303 = "Negócio! Olha, tem um bem difícil ali.",
  str_story_banner_525400304 = "Não se apresse! Vou fazê-lo expor sua fraqueza primeiro, e então vamos desmontá-lo!",
  str_story_banner_525400305 = "Sinto que minha precisão melhorou. Sua câmera é incrível!",
  str_story_banner_525400306 = "Esses Eclipsites foram afligidos com uma Marca de Estaca! Se você atacá-los com um Chain Combo agora, causará mais dano!",
  str_story_banner_5254002011 = "De onde vieram todos esses inimigos!? Vamos colocar esse show na estrada!",
  str_story_banner_5254002012 = "Eles nem saberão o que os atingiu!",
  str_story_banner_5254002013 = "Modo Warsong! Mudança Soprano!",
  str_story_banner_5254002014 = "Esta rota através da conexão de bloco aprimorada deve funcionar! Ignore a barricada inimiga e corra para o palco! Eu preciso cumprimentar meus fãs em sua melhor forma!",
  str_story_banner_52630021 = "Parece que voltei ao campo de batalha novamente.",
  str_story_banner_52630022 = "Embora a mobilidade seja um problema, farei o possível para ajudá-lo.",
  str_story_banner_52630023 = "E assim, o Eclipsite está temporariamente à mercê da minha Chama Ancestral.",
  str_story_banner_52630024 = "Por favor, use minha habilidade para mover o Eclipsite. A Chama Ancestral abrirá um caminho.",
  str_story_banner_52630025 = "Tal poder milagroso! Conte-nos uma história daqueles dias passados, quando tudo acabou.",
  str_story_banner_52630031 = "Que dor... PlayerName, você não me disse que havia Eclipsites tão irritantes quanto esses!",
  str_story_banner_52630032 = "Se atacarmos diretamente, os outros Eclipsites se recuperarão.",
  str_story_banner_52630033 = "Deixe comigo... Eu tenho o remédio perfeito!",
  str_story_banner_52630034 = "Agora este sujeito não vai cair nesta rodada. Arrase-se, velho!",
  str_story_banner_52630035 = "Bom trabalho! Não tenho peixe aqui, mas vou deixar você experimentar um lagarto especial grelhado mais tarde.",
  str_story_banner_52630011 = "Um enxame de Eclipsites embarcou no navio. Não entrar em pânico.",
  str_story_banner_52630012 = "Use Chain Combos o máximo que puder para acender meus Serpent Flares.",
  str_story_banner_52630013 = "Depois de acender os três sinalizadores da serpente, posso usar minha poderosa habilidade ativa para liberar a ira do mar sobre eles!",
  str_story_banner_52630014 = "Acenda um sinalizador de serpente, continue fazendo combos e acenda o resto! Serpent Flares pode ser mais facilmente iluminado durante o Aurora Time.",
  str_story_banner_527200401 = "Pequeno Navegador, é a sua vez de me comandar, quero dizer, Bullock 8.",
  str_story_banner_527200402 = "Meu doce amor! Não o quebre!",
  str_story_banner_527200403 = "Ele realmente é encantador, atraindo tantos Eclipsitas aqui...",
  str_story_banner_527200404 = "Então, a tarefa de eliminar esses resíduos cabe a você!",
  str_story_banner_527200405 = "Ele é diferente do seu Colosso! Ele pode lutar também!",
  str_story_banner_527200406 = "Este carro de corrida tem todos os tipos de dispositivos e armadilhas projetadas para transformar esses canalhas em grãos de areia!",
  str_story_banner_527200411 = "Haha! Em breve, essa escória vai virar pó! Só de pensar nisso me faz sentir melhor.",
  str_story_banner_527200412 = "Depois de cuidar dessa imundície, essa charmosa namorada vai ficar perfeita como a chuva! Você pode montar quantas armadilhas quiser!",
  str_story_banner_527200413 = "Bullock 8 pode recuperar 1 ponto de energia a cada rodada. Claro, limpar esse lixo também pode acumular energia para ele.",
  str_story_banner_527200414 = "Claro, não haverá muitas armadilhas! Afinal, há um limite para tudo, e meu doce amor não é um daqueles caminhões Illumina grandes e feios...",
  str_story_banner_527200415 = "Observe que ele só pode implantar até 6 armadilhas.",
  str_story_banner_527200416 = "Ainda assim, posso pedir ao meu doce amor para remover essas armadilhas, e não vai custar nada!",
  str_story_banner_527200421 = "Essa bola de nojo nojenta... Tem algo estranho nela... Parece que não tem medo dessas armadilhas!",
  str_story_banner_527200422 = "E sua habilidade nojenta pode destruir armadilhas! Minha gracinha celestita, cuidado!",
  str_story_banner_52740011 = "Seriamente? Eu sou um membro sênior agora. Por que ainda tenho que lidar com essas coisas?",
  str_story_banner_52740012 = "Eu realmente quero voltar para a minha leitura. Vamos nos livrar desses aborrecimentos o mais rápido possível.",
  str_story_banner_52740013 = "Cada vez que você toca em um bloco aprimorado, pode selecionar outro ponto de aterrissagem.",
  str_story_banner_52740014 = "Dessa forma, você pode absorver ladrilhos aprimorados com a Habilidade Ativa e aumentar o dano final da sua Habilidade de Equipamento. Vamos nos mexer!",
  str_story_banner_52740021 = "Vou dar o meu melhor nesta missão de entrega!",
  str_story_banner_52740022 = "Shh... vê aqueles Eclipsites ao nosso redor? Vamos nos livrar deles antes de pegarmos a estrada, só por segurança.",
  str_story_banner_52740023 = "Sem problemas!",
  str_story_banner_52740024 = "Aproxime-se deles com habilidade de teletransporte e eu cuidarei do ataque!",
  str_story_banner_52840011 = "PlayerName, Sinto muito por ter que pedir para você me ajudar a lidar com isso.",
  str_story_banner_52840012 = "É porque... só dormi... 12 horas...",
  str_story_banner_52840013 = "Zzzzzzz...",
  str_story_banner_52840014 = "Não se preocupe, Tina pode lutar mesmo quando ela está dormindo.",
  str_story_banner_52840015 = "O método de seleção da habilidade ativa de Tina é diferente dos outros aurorianos. Primeiro, você precisa determinar seu caminho de movimento conectando as peças.",
  str_story_banner_52840016 = "Depois de determinar seu caminho, Tina caminhará como um sonâmbulo ao longo da rota selecionada, mudando a cor dos ladrilhos ao longo de seu caminho e, por fim, retornará ao seu ponto de partida.",
  str_story_banner_52840017 = "Ao conectar os ladrilhos, você também pode conectar o ladrilho inimigo como o ponto final de Tina sem consumir o número de ladrilhos que pode conectar.",
  str_story_banner_52840018 = "Nesta situação, Tina vai parar no ladrilho antes do ponto final e causar dano ao inimigo.",
  str_story_banner_52840019 = "Eclipsos! Como você se atreve a mostrar suas caras sujas em Lumopolis! Isso é absolutamente imperdoável!",
  str_story_banner_52840020 = "Primeiro aumente a velocidade da arma ao máximo e depois lance uma habilidade!",
  str_story_banner_52840021 = "Reforços? Parece que teremos que usar algumas habilidades reais aqui.",
  str_story_banner_52840022 = "Use a Habilidade Ativa! Libere todo o zelo e elimine-os!",
  str_story_banner_52840023 = "Como esses imundos Eclipsites ousam contaminar Lumopolis! Devemos purificá-los!",
  str_story_banner_52840024 = "Plebeu, vou deixar aqueles Eclipsites fracos ali em suas mãos.",
  str_story_banner_52840025 = "Eu limpo o resto.",
  str_story_banner_52840026 = "Eu reuni força suficiente. Agora, é a minha vez de lutar.",
  str_story_banner_5299001 = "I-É aquele carro quebrado de novo! Você se lembra de como nós o desmontamos juntos da última vez?",
  str_story_banner_5299002 = "Primeiro, bata isso Chainsaw Rick b-bloqueando o caminho!",
  str_story_banner_5299003 = "<color=#FFB400>Tocar em um inimigo auroriano mostra sua próxima ação.</color>",
  str_story_banner_5299004 = "<color=#FFB400>Os aurorianos geralmente têm como alvo a unidade inimiga mais próxima.</color>",
  str_story_banner_5299005 = "Mas eles <color=#FFB400>só podem se mover em blocos de seu próprio elemento!</color>\nMantenha a distância e faça o possível para não deixá-los nos machucar.",
  str_story_banner_5299006 = "Th-Isso aqui mostra o ATK e HP do inimigo,\ne direi que é uma maneira muito fácil de avaliar se você está à altura do desafio.",
  str_story_banner_5299007 = "Vamos entrar em ação!",
  str_story_banner_5299008 = "Surpreendente!",
  str_story_banner_5299009 = "Tudo bem, eu e aquele Darkwasp agora estamos esperando suas ordens.\n(Se ao menos eu pudesse deixar o Darkwasp avançar e encontrar um lugar para se esconder...)",
  str_story_banner_5299010 = "O-Oh sim! Lord Augean aperfeiçoou uma nova habilidade! <color=#FFB400>Ao receber dano corpo a corpo, ele agora pode contra-atacar o atacante</color>!\nCertifique-se de aproveitar ao máximo esta habilidade especial!",
  str_story_banner_5299011 = "Oh, não!\nAcabei de ouvir que nosso amigo escondido em Lumopolis foi descoberto e está lutando contra os guardas!\nN-Precisamos nos apressar e ajudá-los!",
  str_story_banner_5299012 = "Eles estão muito longe, então tente usar o <color=#FFB400>buraco de minhoca</color> à frente para chegar lá mais rápido.",
  str_story_banner_5299013 = "Mas ainda há muitos aurorianos bloqueando o caminho...\nSe você quer evitá-los ou não, depende de você.",
  str_story_banner_5299014 = "Barbara!\nouvi dizer que ela pode <color=#FFB400>atacar e nos atordoar</color>... Ela é a-terrorizante!",
  str_story_banner_5299015 = "M-Mas nós temos um forte aliado para nos ajudar—Thumper!\nbatedor pode <color=#FFB400>empurre os alvos para trás 2 quadrados</color>!",
  str_story_banner_5299016 = "Isso não funciona apenas contra os aurorianos, mas você também pode usá-lo em seus aliados do Eclipsite!\nÀs vezes, pode até lhe proporcionar algumas surpresas estratégicas...",
  str_story_banner_5299017 = "De uma chance!",
  str_story_banner_5299018 = "Esta parece ser uma situação semelhante à anterior, mas sem o dano da armadilha.",
  str_story_banner_5299019 = "V-Você deveria começar a pensar em como vai lidar com Barbara...",
  str_story_banner_5299020 = "<color=#FFB400>Talvez Thumper possa nos empurrar para frente?</color>",
  str_story_banner_5299021 = [[
Finalmente chegamos ao LL-Lumopolis!
Vamos derrotar esses Lumo Guards junto com nossos aliados Eclipsite!]],
  str_story_banner_5299022 = "<color=#FFB400>O Assistente Afônico pode restaurar o HP dos nossos aliados Eclipsite dentro do alcance</color>, fornecendo suporte vital!",
  str_story_banner_5299023 = "II-É ele! O homem que se esconde nas profundezas de Lumopolis\n—<color=#FFB400>Schwartz!</color>",
  str_story_banner_5299024 = "Estou com medo, b-mas não podemos recuar...",
  str_story_banner_5299025 = "P-Por favor j-só se renda! ... Pareço falar sério?",
  str_story_banner_5299026 = "De qualquer forma, vamos deixar isso para Lord Augean. Quanto a mim...\nEstarei torcendo por todos na retaguarda! Você... Você consegue!",
  str_story_banner_52940011 = "Droga... eu me machuquei.",
  str_story_banner_52940012 = "Alguns deles ainda estão atrás de mim? Não, esses caras estavam esperando aqui para me emboscar.",
  str_story_banner_52940013 = "Parece que eles se esforçaram muito para criar esses obstáculos.",
  str_story_banner_52940014 = "Mas eles são muito ingênuos se acham que isso vai me impedir.",
  str_story_banner_52940021 = "Cuidado, há Eclipsites à frente.",
  str_story_banner_52940022 = "O ladrilho diagonal na frente é um lugar melhor para atacar. Seria ótimo se eu pudesse me mudar para lá.",
  str_story_banner_52940023 = "Não se preocupe, posso usar minha Variante de Habilidade Ativa para nos levar até lá.",
  str_story_banner_52940024 = "Variantes de Habilidades Ativas são variações de Habilidades Ativas que têm efeitos ligeiramente diferentes. Conjurá-lo afetará a contagem de cooldown da próxima habilidade ativa.",
  str_story_banner_52940025 = "Que minhas torrentes limpem todo o mal!",
  str_story_banner_11900701 = "Você pode realizar o refinamento do equipamento aqui. Vamos dar uma olhada em algumas das coisas que você pode fazer!",
  str_story_banner_11900801 = "Você pode realizar o refinamento do equipamento aqui. Vamos dar uma olhada em algumas das coisas que você pode fazer!",
  str_story_banner_29052011 = "Você pode sentir a morte vindo para você?\nSinta como é a morte para si mesmo.",
  str_story_banner_29052012 = "Isso não é nada...!",
  str_story_banner_29052013 = "É aqui que você vai morrer!",
  str_story_banner_29052014 = "Sua resistência é inútil.",
  str_story_banner_29052015 = "Não não! Isto é impossível!",
  str_story_banner_53040011 = "Eu fui muito fundo? Eu pareço estar cercado por Eclipsites.",
  str_story_banner_53040012 = "Não entre em pânico, precisamos pensar com calma em uma maneira de sair.",
  str_story_banner_53040013 = "Use a habilidade ativa para romper o cerco acima primeiro.",
  str_story_banner_53040014 = "Fraco.",
  str_story_banner_53040015 = "Existem muitos ladrilhos aprimorados ao longo do caminho à direita. Pegá-los aumentará os efeitos de minhas habilidades. Vamos seguir esta rota e eliminar os Eclipsites restantes.",
  str_story_banner_53040016 = "Vou derrotar os inimigos em meu caminho com minha espada. Desenhe sua lâmina!",
  str_story_banner_53040021 = "É raro ter a oportunidade de lutar lado a lado com o Coronel Yingel.",
  str_story_banner_53040022 = "Há muitos inimigos, por favor, crie uma estratégia para nós, coronel Yingel.",
  str_story_banner_53040023 = "Claro. Eu guiarei todos adiante.",
  str_story_banner_53040024 = "Devemos ser capazes de atacar os Eclipsites à distância agora. Vamos terminar isso rapidamente.",
  str_story_banner_53040031 = "Com base no que aprendemos até agora, existem inúmeros Eclipsites espalhados por toda a área. Simplesmente sair correndo e atacá-los não ajudará.",
  str_story_banner_53040032 = "Aqui está o que eu penso: se formos com a abordagem Ode to the Depths, nossa chance de ganhar será de 99%.",
  str_story_banner_53040033 = "Podemos usar Darkness Cometh desde que eles se reuniram em um só lugar.",
  str_story_banner_53040034 = "Com base nas informações que temos, abordar rapidamente os inimigos pode nos dar 90% de chance de vencer.",
  str_story_banner_53040035 = "Vou usar Ode to the Depths para encurtar a distância.",
  str_story_banner_53130031 = "Tenho a sensação de que posso descobrir alguns segredos incríveis de adivinhação aqui. Estou super empolgado!",
  str_story_banner_53130032 = "Espere o que? Como é que existem tantos Eclipsites agora? Eles não estavam lá na adivinhação de ontem!",
  str_story_banner_53130033 = "Deixa para lá! O Livro da Adivinhação terá uma solução!",
  str_story_banner_53130034 = "Está pegando fogo? Bem, pelo menos podemos ver o rastro de luz!",
  str_story_banner_53130021 = "Os Eclipsites estão chegando... Devo proteger este lugar. Esta é minha responsabilidade.",
  str_story_banner_53130022 = "Aquele que emite uma aura esmagadoramente maligna deve ser o líder do Eclipsite. Ataques normais não terão muito efeito sobre ele.",
  str_story_banner_53130023 = "Mas minha espada não é uma arma normal. Corte a cabeça da cobra e o resto do corpo a seguirá.",
  str_story_banner_53130024 = "Várias Lâminas de Dawn foram espalhados. Esta é a oportunidade que esperávamos.",
  str_story_banner_53130025 = " Use Darkness Shattered para recuperá-los - isso aumentará meu ataque normal e reduzirá o tempo de recarga de Days Without End.",
  str_story_banner_53130011 = "Urgh... Fui atingido, e ainda há tantos Eclipsites.",
  str_story_banner_53130012 = "Não se preocupe! Na verdade, eu me sinto muito mais forte agora.",
  str_story_banner_53130013 = "Os Eclipsites estão nos cercando? Tudo bem, é só usar o meu The Summoning para eliminá-los!",
  str_story_banner_53130014 = "Este é o poder de The Summoning... Seu escudo pode impedir que aqueles Eclipsites até mesmo me toquem.",
  str_story_banner_53130015 = "Veja, o escudo entrou em vigor. É hora de lançarmos um contra-ataque.",
  str_story_banner_53130016 = "Não se esqueça de usar o Nascimento de Baba Yaga. O escudo que ele fornece nos tornará invencíveis.",
  str_story_banner_53191011 = "Bem-vindo ao treinamento Luminatics de hoje! Não se preocupe, não é tão difícil quanto parece!",
  str_story_banner_53191012 = "Este é um curso de treinamento especial projetado especificamente para aprimorar sua capacidade de guiar trilhas de luz, para que você não veja nenhum inimigo aparecendo aqui, fique tranquilo!",
  str_story_banner_53191013 = "Toque nas peças do campo para selecionar as peças do mesmo elemento conectadas a elas.",
  str_story_banner_53191021 = "Depois de selecionar um ladrilho, toque na área selecionada novamente para removê-lo.",
  str_story_banner_53191031 = "Quando o número de peças removidas atingir a pontuação mais alta, você terá concluído este desafio!",
  str_story_banner_53191032 = "Agora é tudo com você, Navegador! Experimente você mesmo!",
  str_story_banner_53192011 = "Veja, há muitos ladrilhos Azuis no campo, mas eles estão desconectados no meio.",
  str_story_banner_53192021 = "Então é assim que a luz flui? Espere! Eu tenho uma ideia!",
  str_story_banner_53192031 = "Olhar! Temos tantos blocos azuis conectados agora! Remova-os juntos!",
  str_story_banner_53192041 = "Depois de removê-los, sua pontuação atingiu as condições de classificação e agora você tem a chance de usar Raging Caltrops.",
  str_story_banner_53192051 = "Raging Caltrops pode converter duas peças cromáticas! Experimente você mesmo!",
  str_story_banner_53193011 = "Dois novos membros da equipe chegaram e podem converter ainda mais peças Azuis.",
  str_story_banner_53193012 = "Navegador, é hora de você tomar as rédeas!",
  str_story_banner_53194011 = "Temos um novo conteúdo de treinamento para você... Veja! Uma peça de runa apareceu no campo!",
  str_story_banner_53194021 = "Se você não cuidar dele rapidamente, ele se transformará em um ladrilho quebrado, o que significa um grande problema!",
  str_story_banner_53195011 = "Muitos aurorianos da floresta são especialistas em utilizar ladrilhos aprimorados.",
  str_story_banner_53196011 = "Agora é hora dos aurorianos de fogo se exibirem e assumirem um cenário totalmente novo.",
  str_story_banner_53197011 = "O teste final... Isso não será fácil.",
  str_story_banner_53197012 = "Seu objetivo desta vez é remover o máximo de peças possível dentro do limite da rodada e bater o recorde!",
  str_story_banner_53197013 = "Cada vez que você atingir uma meta de classificação em um estágio de desafio, o estágio será atualizado.",
  str_story_banner_53197021 = "À medida que um estágio é atualizado, sua dificuldade também aumenta!",
  str_story_banner_53197022 = "Navegador, é hora de liberar seu verdadeiro poder!",
  str_story_banner_60121011 = "Conforme você se aproxima da borda do deserto, uma névoa paira no ar, escondendo talvez as criaturas exiladas lá dentro. Apesar de nosso conhecimento limitado deste lugar, não há necessidade de entrar em pânico. Parece que alguém se aventurou aqui antes de nós...",
  str_story_banner_60121012 = "Ranking, Hunting Bounty e Exiled Harborage foram adicionados ao Desolation Codex.",
  str_story_banner_60121013 = "Vamos dar uma olhada neles!",
  str_story_banner_60121031 = "Fiel ao seu nome, o lendário deserto do Desolation Codex contém informações limitadas. No entanto, à medida que você explora seus segredos, você desbloqueia mais recompensas incríveis.",
  str_story_banner_60121032 = "Quando o ciclo atual do Desolation Codex terminar, você receberá Forgotten Utterances e Forgotten Whispers com base em sua classificação.",
  str_story_banner_60121033 = "Você pode trocar Forgotten Utterances e Forgotten Whispers por Solamber, Aurorians e Star Flares no Exiled Harborage.",
  str_story_banner_60121051 = "No Ranking Atual, os navegadores são classificados com base no dano que causam ao chefe. Navegadores de alto escalão recebem emblemas melhores como recompensa.",
  str_story_banner_60121091 = "Desafie o chefe deste ciclo agora!",
  str_story_banner_60122011 = "Conforme você se aproxima da borda do deserto, uma névoa paira no ar, escondendo talvez as criaturas exiladas lá dentro. Apesar de nosso conhecimento limitado deste lugar, não há necessidade de entrar em pânico. Parece que alguém se aventurou aqui antes de nós...",
  str_story_banner_60122012 = "Nossa tarefa no Desolation Codex é enfrentar um Boss conhecido como The Forsaken ou algo assim. As recompensas que recebemos, como classificações, emblemas e Lumamber, serão determinadas pelo dano que infligimos ao chefe.",
  str_story_banner_60122051 = "Você pode ver os padrões de dano e as recompensas de todos os níveis aqui.",
  str_story_banner_60122052 = "Ao final de cada ciclo, recompensas e emblemas serão distribuídos de acordo com sua classificação. Quanto mais altas forem suas classificações, maiores serão as recompensas.",
  str_story_banner_60122053 = "Seu emblema será exibido em seu avatar pessoal como um símbolo de suas conquistas.",
  str_story_banner_60122054 = "Quando o ciclo atual do Desolation Codex terminar, você receberá Forgotten Utterances e Forgotten Whispers com base em sua classificação.",
  str_story_banner_60122055 = "Você pode trocar Forgotten Utterances e Forgotten Whispers por Solamber, Aurorians e Star Flares no Exiled Harborage.",
  str_story_banner_60122071 = "Na classificação atual, os navegadores são classificados com base no dano que causam ao chefe. Navegadores de alto escalão recebem emblemas melhores como recompensa.",
  str_story_banner_60122111 = "Desafie o chefe deste ciclo agora!",
  str_story_banner_53240021 = "Veja, Eclipsites apareceram à distância! Mas não se preocupe! Eu te dou cobertura!",
  str_story_banner_53240022 = "Esquisito. Como não foram eliminados...",
  str_story_banner_53240023 = "Ah, então os Eclipsitas bloquearam o caminho com ladrilhos quebrados, impedindo que nos aproximássemos do ataque!",
  str_story_banner_53240024 = "Parte do meu trabalho é remover todos os obstáculos e abrir o caminho para você.",
  str_story_banner_53240025 = "Lançar habilidade ativa para conectar mais peças. Então usarei o Chain Combo para remover esses obstáculos.",
  str_story_banner_53240011 = "Parece que vai ser um dia tranquilo hoje, PlayerName.",
  str_story_banner_53240012 = "Oh? Eclipsitos? Uma oportunidade perfeita para alongar os músculos.",
  str_story_banner_53240013 = "Este Eclipsite é fraco. Vamos cuidar do da esquerda primeiro.",
  str_story_banner_53240014 = "PlayerName, ele entrou no estado de Sabedoria Sagrada e ganhou pontos de Sabedoria. Você pode ver o marcador acima de sua barra HP.",
  str_story_banner_53240015 = "Ao causar dano a inimigos no estado de Sabedoria Sagrada, posso ignorar seus escudos e converter o dano em pontos de Sabedoria.",
  str_story_banner_53240016 = "Quando os pontos de Sabedoria excedem o HP atual do inimigo, posso matá-lo independentemente de seu escudo. Vamos terminar isso rapidamente!",
  str_story_banner_53340021 = "PlayerName, o primeiro passo para um homem maduro é sempre manter a calma.",
  str_story_banner_53340022 = "É um pouco chato agora, mas vou resolver isso rapidinho.",
  str_story_banner_53340023 = "Vou coletar azulejos azuis com meu poder para acionar De Dawn Até o Anoitecer para cura.",
  str_story_banner_53340024 = "Próximo, Passo 2: Aprenda a lidar com os contratempos",
  str_story_banner_53340025 = "Minha Habilidade Ativa, Dança dos Sonhos Despertos, pode embaralhar as linhas e colunas com apenas alguns toques. Agora, é sua vez.",
  str_story_banner_53340011 = "Eclipsitas no meu território? Isso ameaça meu investimento! Só observem, vou mostrar a porta pra eles eu mesmo!",
  str_story_banner_53340012 = "Use o Jackpot para enviá-los para longe!",
  str_story_banner_53340013 = "Desviamos um pouco. Precisamos cobrir um pouco mais de terreno para voltar ao rumo certo.",
  str_story_banner_53340014 = "Arrase ou vá para casa! E a melhor parte é—O Risco é Todo Seu.",
  str_story_banner_53340015 = "EveTodos prontos! Vamos acabar com eles de uma vez!",
  str_story_banner_80010101 = "Navegador, parece Eve está preso em um sonho!",
  str_story_banner_80010201 = "O que está acontecendo comigo? Minha cabeça está girando...",
  str_story_banner_80010301 = "Para onde foi a sombra...?",
  str_story_banner_80010401 = "O que a sombra deixou cair?",
  str_story_banner_53340031 = "Os inimigos estão espalhados, então precisamos implantar um Lagarto de Ferro no centro para puxá-los para a eliminação.",
  str_story_banner_53340032 = "Toque no Iron Lizard e, a cada rodada, você pode usar Magnetix ou Whirlpool para se adaptar à situação do campo de batalha!",
  str_story_banner_53440021 = "Os Eclipsitas estão chegando. É minha responsabilidade proteger este lugar!",
  str_story_banner_53440022 = "Libere o Blitz Sagrado no inimigo com o maior número de acúmulos de Vontade Persistente!",
  str_story_banner_53440023 = "Criaturas da escuridão perpétua! Sintam o poder do Deus da Luz!",
  str_story_banner_53430011 = "Vamos aquecer, PlayerName, começando pelo maior!",
  str_story_banner_53430012 = "Com o novíssimo Barão Vermelho, seu poder pode ser amplificado em condições específicas. Lembre-se disso para as próximas batalhas.",
  str_story_banner_53430013 = "Inimigos atacados por Habilidades Ativas são levados a entrar no estado de Eco Trovejante. Sempre que eu faço um movimento, eu causo dano aos inimigos sob o estado de Eco Trovejante nas proximidades.",
  str_story_banner_53430014 = "Agora, por favor me guie, PlayerName. Vou mostrar minha força.",
  str_story_banner_50620001 = "Sério, PlayerName? Com medo desses Eclipsitas?",
  str_story_banner_50620002 = "Não se preocupe. A justiça pode ser tardia, mas minhas videiras e eu nunca somos.",
  str_story_banner_50620003 = "Vamos acabar com isso; é mais um dia monótono.",
  str_story_banner_50620011 = "PlayerName, estou encantado por você estar comigo nesta patrulha na floresta.",
  str_story_banner_50620012 = "Parece que não apenas os Eclipsitas se escondem aqui, mas a própria terra está poluída.",
  str_story_banner_50620013 = "Não se preocupe; com sua ajuda, vamos resolver isso.",
  str_story_banner_50620014 = "Este é o poder da purificação. Hora de derrubar esses Eclipsitas.",
  str_story_banner_80020101 = "Pam? Por que você está de volta novamente?",
  str_story_banner_80020102 = "V-Você é... Senhora Irridon? Mal reconheci você com essa roupa.",
  str_story_banner_80020103 = "Preciso ir e recorrer! Não posso deixar minha família sofrer essa injustiça!",
  str_story_banner_80020104 = "Agora não é a hora!",
  str_story_banner_80020105 = "Até você está tentando me parar?",
  str_story_banner_80020106 = "Agora, saia imediatamente, a menos que consiga me derrotar!",
  str_story_banner_80020201 = "É aquele... Mirren Gautier?!",
  str_story_banner_80020202 = "Ele é a raiz de todos os nossos problemas, trazendo desgraça para nossa família.",
  str_story_banner_80020203 = "Oh, Deus da Luz, se você pode ver isso, por que deixá-lo andar livre? Não pretende nos proteger?",
  str_story_banner_80020204 = "Agora não tenho escolha a não ser resolver as coisas com minhas próprias mãos!",
  str_story_banner_80020301 = "Melhor ainda... Quem é você, afinal?",
  str_story_banner_80020302 = "Juiz Chefe, minha família e eu fomos injustamente acusados, e esperamos que você possa nos ajudar a buscar justiça e limpar nossos nomes!",
  str_story_banner_80020303 = "Então, você é considerado culpado?",
  str_story_banner_80020304 = "Cada julgamento proferido pelo Tribunal de Justiça é sancionado pelo Deus da Luz, sem absolutamente nenhuma margem para erro.",
  str_story_banner_80020305 = "Sendo uma parte culpada, você se recusou a admitir seu erro e enfrentar a punição e invadiu ilegalmente o Tribunal de Justiça, profanando nossos julgamentos sagrados...",
  str_story_banner_80020306 = "Você é simplesmente hediondo e merece ser punido ainda mais!",
  str_story_banner_80020307 = "...",
  str_story_banner_53540021 = "PlayerName, ainda temos alguma distância a percorrer, mas estamos quase lá.",
  str_story_banner_53540022 = "Se perdermos essa oportunidade de observação, quem sabe quanto tempo teremos que esperar pela próxima.",
  str_story_banner_53540023 = "Nunca pensei que encontraríamos Eclipsitas aqui! Fique perto de mim!",
  str_story_banner_53540024 = "Nós receberemos cura extra se nos posicionarmos na área escolhida. Acredito que você possa aproveitar isso.",
  str_story_banner_53540011 = "Então, é assim que o mundo lá fora se parece...",
  str_story_banner_53540012 = "Mesmo sem minha irmã ao meu lado, encontrarei coragem para lutar!",
  str_story_banner_53540013 = "Posso converter livremente as peças Amarelas ou Verdes selecionadas em peças Azuis.",
  str_story_banner_53540014 = "Vamos começar lançando a Tempestade de Granizo Invernal e dar à terra um toque gelado!",
  str_story_banner_53540015 = "Você não pode usar o poder da neve e do vento consecutivamente. Tente lançar o Apagão Eterno Verde na próxima rodada!",
  str_story_banner_53540031 = "Procurando sinais... Inimigo avistado. Desdobrando o Reino e pronto para coletar dados!",
  str_story_banner_53540032 = "Durante a contagem regressiva, os Navegadores podem trocar os elementos das casas adjacentes para planejar uma rota de ataque mais adequada.",
  str_story_banner_700102 = "A lista de desejos está disponível neste recrutamento por tempo limitado, e a lista de desejos contém 1 Auroriano fixo e 4 Aurorianos de sua escolha.",
  str_story_banner_700103 = "Selecione um Auroriano de 6 estrelas de cada um dos quatro elementos para os 4 Aurorianos opcionais restantes.",
  str_story_banner_700104 = "A lista de desejos entra em vigor após a determinação dos 4 Aurorianos.",
  str_story_banner_700105 = "Quando a lista de desejos entra em vigor, todos os Aurorianos 6 estrelas recrutados têm a garantia de pertencer à lista de desejos.",
  str_story_banner_501400511 = "Não acredito que há tantos Eclipsitas na Baía dos Pavilhões Gêmeos! Tenha cuidado ao lidar com eles para evitar prejudicar os moradores próximos.",
  str_story_banner_501400512 = "Preste muita atenção às posições dos inimigos! Parece haver um caminho de ladrilhos vermelhos que pode ser utilizado; Use as Begônias Brilhantes para conectá-lo!",
  str_story_banner_501400513 = "Toma essa!",
  str_story_banner_501400514 = "Com o caminho conectado, os grandes Eclipsitas à frente foram <color=#FFB400>eliminados</color> pelas Begônias Brilhantes. Agora, siga para a parte nordeste do campo de batalha para lidar com os Eclipsitas restantes!",
  str_story_banner_501400515 = "Hã? A ampulheta no chão parece ter sido criada logo após o seixo se quebrar, oferecendo uma ótima chance de reduzir o tempo de recarga das Begônias Brilhantes. Vamos experimentar os ladrilhos verdes desta vez!",
  str_story_banner_501400611 = "Há muitos Eclipsitas! Mas temos que ser rápidos. Todos, fiquem seguros!",
  str_story_banner_501400612 = "Os caminhos ao redor deste Eclipsita são todos vermelhos. Vamos começar usando Begônias Brilhantes para conectar o caminho e então <color=#FFB400>lançar Ataques Normais neste Eclipsita de diferentes direções</color>, maximizando o efeito de Nos Momentos de Necessidade!",
  str_story_banner_501400613 = "Excelente! Vamos aproveitar esse impulso e eliminar todos os Eclipsitas!",
  str_story_banner_81001011 = "Lembre-se, PlayerName? Um cubo estranho apareceu no Obelisco do Retorno!",
  str_story_banner_81001012 = "Parece que esse cubo pode ativar um dispositivo de treinamento Luminatics projetado pelos Celestitas...",
  str_story_banner_81002011 = "Alerta: O treinamento começou oficialmente. Você enfrentará continuamente múltiplos estágios em cada sessão de treinamento.",
  str_story_banner_81003011 = "Se você ficar sem rodadas ou for derrotado, a sessão de treinamento atual será encerrada e você não poderá continuar seu desafio.",
  str_story_banner_81003012 = "Após concluir com sucesso todas as etapas, a rodada atual de treinamento chegará ao fim. Boa sorte, Pai.",
  str_story_banner_81004011 = "Módulo de treinamento ativado...",
  str_story_banner_81004012 = "Durante o programa de treinamento, basta tocar e remover as peças para combater os Eclipsitas.",
  str_story_banner_81004013 = "Toque nos ladrilhos para selecionar ladrilhos do mesmo elemento conectados a eles. Ao fazer isso, você verá uma prévia do Combo em Cadeia do Aurorian.",
  str_story_banner_81004014 = "Experimente por si mesmo.",
  str_story_banner_81005011 = "Tocar novamente nos ladrilhos selecionados os removerá, e os Aurorianos do mesmo elemento que os ladrilhos lançarão seus Combos em Cadeia.",
  str_story_banner_81006011 = "Continue a batalha e derrote todos os inimigos para completar o treinamento.",
  str_story_banner_53740021 = "Será que realmente conseguirei cobrar alguma dívida aqui?",
  str_story_banner_53740022 = "Tsk, em vez de encontrar vagabundos, encontrei alguns Eclipsitas.",
  str_story_banner_53740023 = "É melhor eu acabar com todos eles rapidamente. Estou começando a sentir falta de Rebecca agora.",
  str_story_banner_53740011 = "Eclipsitas... Por que eles estão aqui?",
  str_story_banner_53740012 = "Vou tentar me aproximar deles e fazê-los \"sair\" sem dor...",
  str_story_banner_53740013 = "Use a Habilidade Ativa Dança das Borboletas para converter as casas Azuis ao redor dos monstros em casas Escuras.",
  str_story_banner_53740014 = "Após passar por um Dark Tile, o elemento do ladrilho que é atualizado ali deve ser o mesmo de antes.",
  str_story_banner_53740015 = "Pare de resistir a mim. Isso acabará em um instante e não vai doer... muito.",
  str_story_banner_551103 = "Dê uma olhada, navegador. Uma nova área surgiu. Vamos conferir!",
  str_story_banner_53840011 = "Nas enigmáticas profundezas do mar, abundam navios naufragados, escondendo inúmeras maravilhas de Longzhou sob as ondas. Felizmente, com a ajuda da perícia mecânica, podemos tentar resgatar os restos do navio, trazendo esses tesouros enterrados de volta à luz do dia.",
  str_story_banner_53840021 = "Por favor, esteja ciente de que quando a área de resgate estiver cheia, o resgate terminará em fracasso!",
  str_story_banner_53840031 = "Conquiste a vitória ao resgatar com sucesso todas as relíquias no campo!",
  str_story_banner_53840032 = "Navegador, agora está em suas mãos!",
  str_story_banner_53840041 = "Prepare-se para o desafio definitivo!",
  str_story_banner_53840042 = "Aqui, as relíquias são abundantes e você deve se esforçar para resgatar o máximo de relíquias possível dentro do tempo limitado!",
  str_story_banner_53840043 = "Ao final, as recompensas serão distribuídas com base na pontuação adquirida.",
  str_story_banner_53840044 = "Navegador, é hora de mostrar suas verdadeiras habilidades!",
  str_story_banner_53840111 = "Por que há tantos Eclipsitas aqui de repente? O da esquerda parece especialmente difícil. Precisamos montar um Esquadrão Trovão Quadrado e lutar com cuidado.",
  str_story_banner_53840112 = "Use o Puxão de Guarda-sol para eliminar todos os outros inimigos espalhados por toda parte.",
  str_story_banner_53840113 = "É extremamente vantajoso para nós enfrentar inimigos no Array do Trovão Quadrado. Use-o bem para vencer todas as suas batalhas!",
  str_story_banner_53940311 = "Uau, estou cercado por Eclipsitas. Só porque sou pequeno não significa que sou fácil de ser intimidado.",
  str_story_banner_53940312 = "Ouvi dizer que alguns Eclipsitas roubam antiguidades... Eles realmente sabem o que estão roubando...?",
  str_story_banner_53940313 = "Use a Exposição Total e aproxime-se deles para examiná-los cuidadosamente.",
  str_story_banner_53940211 = "Ah, é você, Sr. Istvan. Suas roupas...",
  str_story_banner_53940212 = "Esqueça isso por enquanto, garotinha. Vamos resolver o problema em questão primeiro.",
  str_story_banner_53940213 = "O jogo de xadrez começou.",
  str_story_banner_53940214 = "Garotinha, mostre-me sua habilidade de controlar a Espada Mágica.",
  str_story_banner_53940215 = "Obrigado por me ajudar, Senhor Sombrio.",
  str_story_banner_53940216 = "O jogo está decidido. É hora de acabar com essa farsa.",
  str_story_banner_53940217 = "Minhas sombras preencherão as lacunas e a tornarão completa.",
  str_story_banner_53940111 = "Selecione Estratégias de Investimento durante a batalha para aprimorar as habilidades de Sheol em todos os aspectos.",
  str_story_banner_53940112 = "O Capital obtido nas batalhas será exibido em uma área designada. Toque nisso para ir para Estratégia de Investimento.",
  str_story_banner_53940113 = "As seis habilidades aqui são divididas em três grupos e serão desbloqueadas à medida que Sheol acumula mais Capital. Sempre que cada grupo é desbloqueado, selecione uma das duas habilidades e toque em Investir para obter essa habilidade. A seleção não pode ser alterada nesta batalha.",
  str_story_banner_53940114 = "Após completar a primeira rodada de investimento, Sheol pode fazer uma segunda rodada de investimento para obter uma habilidade de combate que não tinha na primeira rodada de investimento.",
  str_story_banner_53940115 = "Você atualmente tem 5 Capitais. Tente fazer um investimento em Shadow Snake Entanglement e Rich and Powerful agora para ver o que acontece.",
  str_story_banner_53940116 = "A Habilidade Ativa e o Combo em Cadeia foram atualizados! Investimentos também podem ser feitos em batalhas subsequentes para obter habilidades bloqueadas.",
  str_story_banner_8024001 = "Os inimigos parecem estar fora de alcance.",
  str_story_banner_8024002 = "Bem, já que é assim, deixe-me tentar uma abordagem diferente para o combate.",
  str_story_banner_8024003 = "Em seguida, deixe-me tentar.",
  str_story_banner_8024004 = "Novos inimigos apareceram. Deixe-me cuidar deles.",
  str_story_banner_8024005 = "Posso sentir o poder do Nó de Formação agora. Vamos tentar eliminar todos os inimigos.",
  str_story_banner_5414011 = "Ei PlayerName, encontrei muitas coisas legais por aí neste mundo desde que acordei. Você se importaria de se juntar a mim para conferir isso hoje?",
  str_story_banner_5414012 = "Mas como a Donzela do Dragão, preciso lidar com os problemas próximos primeiro.",
  str_story_banner_5414013 = "Não há muitas oportunidades para eu mostrar minhas habilidades, então é melhor você valorizá-las.",
  str_story_banner_5414014 = "Tudo bem, me observe enquanto eu lido com essa bagunça!",
  str_story_banner_5414031 = "À medida que o Festival da Primavera se aproxima, espíritos malignos estão causando problemas novamente.",
  str_story_banner_5414032 = "Os inimigos estão agrupados no canto, e os métodos convencionais não parecem ser capazes de eliminá-los todos de uma vez. Este é o momento perfeito para usar minha habilidade ativa: Granada Surpresa! Vamos lá, Ah Ding, vamos marcar as posições dos inimigos e eliminá-los com dano de respingos!",
  str_story_banner_5414033 = "Ah, esqueci de te contar, minha Granada Surpresa possui várias variantes. Você pode escolher conjurar uma das várias habilidades variantes, cada uma com um período de recarga diferente após a conjuração.",
  str_story_banner_5414034 = "A Variante I da Granada Surpresa aumenta os Ataques Normais, enquanto a Variante II da Granada Surpresa concede o efeito de repulsão aos Combos em Cadeia após serem lançados. Selecione sabiamente diferentes habilidades variantes com base na situação para maximizar seu dano!",
  str_story_banner_54193101 = "Dizem que eu enlouqueci... Você também está louco? Assim como eu?",
  str_story_banner_54193102 = "Louco? Hehe... Hahaha! Me chame de louco se quiser.",
  str_story_banner_54193103 = "Claymore, você... Está tentando esconder sua verdadeira identidade sob esse nome? Aquiles, me diga, o que está acontecando?!",
  str_story_banner_54193104 = "Eu preciso te levar para baixo...",
  str_story_banner_54193105 = "É isso que está acontecendo aqui!",
  str_story_banner_54193106 = "Adras",
  str_story_banner_54193107 = "Aquiles",
  str_story_banner_16022511 = "Hmph! Acha que pode me prender apenas agindo juntos?",
  str_story_banner_16022512 = "Não se preocupe. Para um caçador incrível como eu, a presa está cheia de pontos fracos!",
  str_story_banner_16022513 = "Durante a caçada, a presa frequentemente revela muitos pontos fracos. A primeira regra da caça é encontrar e explorar esses pontos fracos!",
  str_story_banner_16022514 = "Uma vez que eu pegue seus pontos fracos, essas presas não terão chance contra minha lança!",
  str_story_banner_900107011 = "Comentário: Memórias e emoções deixadas pelos sonhadores originais são envolvidas camada por camada na energia do sonho, formando Orbes de Sonho.",
  str_story_banner_900107012 = "Como seu Enlightener, tenho que lembrá-lo de que durante a exploração, você terá a chance de obter Dream Orbs espalhados por todo o sonho.",
  str_story_banner_900107013 = "Ao colocar Orbes dos Sonhos na Espiral do Iluminismo, você pode analisar as memórias de combate dentro dos Orbes dos Sonhos, desbloqueando habilidades relacionadas para auxiliar os Aurorians na batalha.",
  str_story_banner_900108011 = "Dica: O Enlightener mudará para o modo Cubo de Iluminação, permitindo que ele lute ao lado dos Aurorians.",
  str_story_banner_900108012 = "Em batalha, o Enlightener ganha 1 ponto de energia para cada ladrilho que os Aurorianos atravessam.",
  str_story_banner_900108013 = "Após os Aurorianos terminarem de conectar as peças e todos os seus Combos serem liberados, se o Enlightener tiver acumulado mais energia do que a necessária pelos Orbes dos Sonhos, você pode então liberar as habilidades dos Orbes dos Sonhos na Espiral da Iluminação.",
  str_story_banner_900108014 = "Agora você pode tentar conectar os ladrilhos uma vez.",
  str_story_banner_900108021 = "Boas notícias: Você obteve energia. Você pode visualizar o status de carregamento e os detalhes da montagem dos Orbes dos Sonhos aqui.",
  str_story_banner_900108031 = "Comentário: Existem muitos tipos de Orbes dos Sonhos, entre os quais os Orbes de Carregamento podem ajudá-lo a obter energia adicional e acelerar o progresso do carregamento.",
  str_story_banner_900108032 = "Enquanto isso, os Orbes de Aprimoramento podem fortalecer os Orbes de Habilidade na Espiral de Iluminação.",
  str_story_banner_900108033 = "Combinações sábias podem liberar o potencial total das Orbes dos Sonhos. Como seu Enlightener, acredito que você certamente encontrará alegria nisso.",
  str_story_banner_5416011 = "Eclipsitas apareceram à frente? Parece um trabalho para os Caçadores de Águia.",
  str_story_banner_5416012 = "Mantenha sua posição e use o Death Recon para explorar uma rota de infiltração.",
  str_story_banner_5416013 = "Relatório! O Caçador Águia Zero infiltrou-se no território inimigo; chegou a hora de começar nosso ataque! Solicitamos que todos os drones ataquem o inimigo!",
  str_story_banner_5416014 = "Tente usar o Death Recon novamente! Isso me colocará no status Exausto e me impedirá de usar ataques normais ou combos em cadeia... Mas os Caçadores de Águia travarão no inimigo e o eliminarão em meu lugar!",
  str_story_banner_5416021 = "Boas notícias, o Último Celestita! Hoje, você tem o privilégio de lutar ao lado do lendário Zeta, o salvador de todos os Astra!",
  str_story_banner_5416022 = "Você já conheceu meu outro membro do grupo, certo? Estou falando sobre este robô explosivamente adorável - Conan, o Iluminado!",
  str_story_banner_5416023 = "Conan, o Iluminado, não obedece a ninguém além de mim! Bem legal, né?",
  str_story_banner_5416024 = "Você faria bem em lembrar disso, o Último Celestita: uma vez que o Quadro de Cores estiver coberto com todas as quatro cores, você pode invocar um novo Conan, o Iluminado! Eu não compartilho essa habilidade secreta com qualquer um, então mantenha isso em segredo, ok?",
  str_story_banner_5466011 = "Estou prestes a estabelecer um novo recorde para Tetrablox! Mas existem Eclipsitas... Não tem jeito. Vou ter que te eliminar para conseguir mais pontos!",
  str_story_banner_5466012 = "Primeiro, obtenha a Próxima Fila!",
  str_story_banner_5466013 = "O bloco que você vê no meio da tela é o alcance de conversão de ladrilhos da Habilidade Ativa neste momento.",
  str_story_banner_5466014 = "Toque no botão à direita para gastar Energia e embaralhar a forma.",
  str_story_banner_5466015 = "Esta forma é exatamente o que você precisa!",
  str_story_banner_5466016 = "Não desperdice sua Energia restante! Toque no botão à esquerda para travar a forma primeiro, depois toque no da direita para aprimorá-la!",
  str_story_banner_5466017 = "Foi aprimorado! Na próxima vez que você usar a Habilidade Ativa, gerará um número de Ladrilhos Escuros igual ao número de aprimoramentos dentro do alcance da habilidade.",
  str_story_banner_5466018 = "Agora é a hora! Use a Habilidade Ativa para eliminar os Eclipsitas!",
  str_story_banner_5486011 = "PlayerName, você deveria sair mais e aproveitar a luz do sol.",
